                'mm_step3' => 'Integrasjoner → Utgående webhooks → Legg til. Velg support-kanalen, lim inn webhook-URL-en fra kanallisten, la utløserord stå tomme. Lim deretter inn webhookens token i feltet over og lagre. Full veiledning:',
