        ],
        'intros' => [
            'custom_fields' => 'Lag de ekstra opplysningene en type sak trenger - for eksempel startdato og brukernavn for en ny ansatt - og velg hvilke sakstyper hver av dem gjelder for. Hvert felt avgjør selv om det må fylles ut når en sak registreres, når den lukkes, eller begge deler, og om bestilleren blir spurt om det i portalen.',
            'checklists' => 'En sjekkliste kan merke trinn som obligatoriske. Dette bestemmer hva som skjer hvis noen lukker en sak før de trinnene er krysset av.',
            'mandatory_fields' => 'Velg hvilke saksfelt som må fylles ut før en sak lukkes, og hva som skjer når noen lukker en med noen av dem tomme. Regelen gjelder overalt en sak kan lukkes: sakskjermen, massehandlinger, REST API-et og arbeidsflyter.',
            'departments' => 'Avdelinger grupperer og ruter saker til riktig del av organisasjonen — opprett dem servicedesken din bruker til å kategorisere og fordele arbeid.',
            'teams' => 'Team avgjør hvilke avdelinger analytikere har tilgang til. Tildel avdelinger til team, og tildel så analytikere til team for å styre tilgangen deres.',
            'ticket_types' => 'Sakstyper klassifiserer hva en henvendelse er (for eksempel hendelse eller tjenesteforespørsel) — definer typene analytikere kan sette på en sak.',
            'ticket_origins' => 'Sakskilder registrerer hvordan en sak kom inn (for eksempel e-post, telefon eller portal) — definer kildene analytikere kan velge mellom.',
            'mailboxes' => 'Postkasser kobler FreeITSM til e-postkontoer slik at innkommende meldinger blir saker og svar går ut igjen — legg til og autentiser dem servicedesken din overvåker.',
            'privacy' => 'En sak inneholder ikke bare samtalen din med den som meldte den inn. Videresender du til en leverandør, eller setter en kollega på kopi, havner den meldingen på den samme saken — og svaret deres lander der også. Dette avgjør hvor mye av det innmelderen ser i selvbetjeningsportalen.',
            'indexing' => 'Teksten inne i vedlegg leses slik at den kan søkes i. Word-, Excel-, PowerPoint- og ren tekstfiler leses av FreeITSM selv, i det de kommer inn. PDF-er, eldre Office-filer og skannede dokumenter trenger en egen dokumentlesingstjeneste — sett den opp under <strong>System &rarr; Integrasjoner &rarr; Apache Tika</strong> — og fordi de tar mye lengre tid, leses de i bakgrunnen. Disse to bryterne avgjør når det bakgrunnsarbeidet skjer.',
            'merge_behaviour' => 'Når to saker viser seg å være det samme, kan en analytiker slå dem sammen. Disse innstillingene avgjør hva det gjør med saksreferansene innmelderne dine sitter med, og hva som skjer med samtalene. De gjelder for alle — en sammenslåing endrer hva kunden ser, så to analytikere på samme postkasse må ikke kunne være uenige om det.',
            'reply_templates' => 'Standardsvar analytikerne dine kan sette inn i et svar i stedet for å skrive dem på nytt. Dette er de delte som hele teamet ser — en analytikers egne private maler lagres fra svarvinduet og står ikke oppført her.',
            'rota_shifts' => 'Skift er malene for arbeidsmønster (for eksempel Tidlig, Sen, Beredskap) som analytikere settes opp på i bemanningsplanen — definer dem her før du bygger vaktlisten.',
            'analysts' => 'Analytikere er de ansatte som logger inn og jobber med saker — legg dem til, tilbakestill passord og tildel dem til team for å styre tilgangen deres.',
            'general' => 'Generelle innstillinger styrer hvordan saker oppfører seg - gjenåpning, utsettelse og hvor lenge meldinger og tråder vises.',
            'statuses' => 'Tilstandene i arbeidsflyten en sak kan være i. Statuser merket som <em>Lukket</em> teller som avsluttende — de brukes av rapporter, tellerne i Watchtower og det automatiske tidsstempelet for lukking ved tildeling. Nøyaktig én status er standard for nye saker.',
            'priorities' => 'Prioritetsnivåene som vises på saker. Nøyaktig én prioritet er standard for nye saker.',
            'rota_locations' => 'Hvor hver analytiker jobber en gitt dag — brukes av bemanningsplanen og vises som et farget merke på hver oppføring. Nøyaktig ett sted er standard for nye vaktlisteoppføringer.',
            'email_templates' => 'Automatiske e-postsvar som utløses av hendelser på saker. Bare den første aktive malen per hendelse brukes.',
        ],
        'messaging' => [
            'channels_heading' => 'Meldingskanaler',
            'channels_intro' => 'La kunder prate med en analytiker over WhatsApp — hver melding blir en sak, akkurat som e-post. Legg til en kanal nedenfor, og lim så <strong>webhook-URL-en</strong> til den inn hos leverandøren din (Twilio eller Meta) slik at innkommende meldinger når fram til denne installasjonen.',
            'base_url_label' => '<strong>Offentlig grunn-URL</strong>',
            'base_url_placeholder' => 'https://ditt-domene.no  (eller ngrok-adressen din mens du tester)',
            'base_url_help' => 'Adressen leverandører bruker for å nå denne installasjonen. Setter du den, blir webhook-URL-ene nedenfor klare til å kopieres rett inn. La den stå tom for å bruke den adressen du surfer fra. Tester du lokalt? Kjør <code>ngrok http 80</code> og lim inn <code>https://…ngrok-free.dev</code>-adressen den skriver ut.',
            'templates_heading' => 'Meldingsmaler',
            'templates_intro' => 'Forhåndsgodkjente maler lar en analytiker svare <strong>etter at 24-timersvinduet er lukket</strong>. WhatsApp tillater bare fritekst innen 24 timer etter kundens siste melding; utenfor det kan bare en mal Meta/Twilio har godkjent, sendes. Opprett og få malen godkjent hos leverandøren din, og legg så inn definisjonen her (med plassholderne <code>{{1}}</code> og <code>{{2}}</code>) slik at analytikere kan velge og fylle den ut.',
