        'sla' => [
            'heading' => 'Tjenestenivåavtaler',
            'intro' => 'SLA-er som tar hensyn til arbeidstid, med mål for responstid og løsningstid per prioritet. Klokken stopper på statuser merket «Setter SLA på pause» under <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">Statuser-fanen</a>. Se <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">designnotatene</a>.',
            'global_heading' => 'Globale innstillinger',
            'enforce_from' => 'Håndhev SLA-er fra',
