            'targets_heading' => 'SLA-mål per prioritet',
            'targets_intro' => 'Responstid og løsningstid for hver sakprioritet. Tidene er i minutter (60 = 1 time, 240 = 4 timer, 1440 = 1 døgn). Kalenderen avgjør hvilken arbeidstid klokken går mot. La feltet stå tomt for å hoppe over det målet.',
            'col_priority' => 'Prioritet',
            'col_response_mins' => 'Respons (min)',
            'col_resolution_mins' => 'Løsning (min)',
            'col_calendar' => 'Kalender',
            'col_save' => 'Lagre',
            'calendars_heading' => 'Arbeidskalendere',
            'calendars_intro' => 'Definer arbeidstid, tidssoner og lister over helligdager. Kalendere brukes av SLA-målene (ovenfor) og av enkeltprioriteter. Én kalender er standard for nye prioriteter.',
            'col_name' => 'Navn',
            'col_timezone' => 'Tidssone',
            'col_hours' => 'Timer',
            'col_holidays' => 'Helligdager',
            'col_default' => 'Standard',
            'default_badge' => 'Standard',
            'no_active_priorities' => 'Ingen aktive prioriteter - legg til noen i fanen Prioriteter.',
            'no_calendars' => 'Ingen kalendere definert ennå. Legg til en ovenfor.',
            'col_actions' => 'Handlinger',
            'notifs_heading' => 'Varsler ved brudd',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Slik virker varslingsreglene</strong>Hver regel har fire deler: et <strong>omfang</strong>, en <strong>utløser</strong>, et <strong>mål</strong> og en liste over <strong>mottakere</strong>.<br><br><strong>Omfang</strong> er enten <em>Standard</em> (regelen gjelder saker i alle avdelinger) eller en <em>bestemt avdeling</em> (regelen gjelder bare saker i den avdelingen).<br>Når en sak vurderes, ser systemet først etter en regel som passer avdelingen dens &mdash; finnes den, vinner den regelen, og standarden ignoreres. Finnes det ingen avdelingsspesifikk regel, brukes standardregelen. Slik kan du sette fornuftige standarder som dekker alle avdelinger, og så skjære ut unntak der ett team har andre behov for eskalering.<br><br><strong>Utløser</strong> er enten <em>Advarsel</em> (saken har passert advarselsterskelen &mdash; et mulig brudd nærmer seg) eller <em>Brudd</em> (saken har nå overskredet SLA-målet sitt &mdash; et faktisk brudd). Hver av dem er sin egen regel, så du kan varsle ulike personer ved advarsler og ved brudd.<br><br><strong>Mål</strong> er hvilken SLA-klokke som skal følges &mdash; <em>Respons</em>, <em>Løsning</em> eller <em>Begge</em>.<br><br><strong>Mottakere</strong> kan være en hvilken som helst kombinasjon av: den saken er tildelt akkurat nå, alle analytikere i teamene til saksavdelingen, én navngitt analytiker og/eller en liste med frie e-postadresser (nyttig for delte innbokser eller e-postbroer til Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Ingen regler = ingen e-poster.</strong> Selv om en sak bryter SLA-en, skjer det ingenting før du legger til minst én regel (start med et par på standardomfang, ett for advarsel og ett for brudd, så har du dekning for alt).',
            'notifs_dedup' => 'Hver sak utløser høyst én e-post per mål per utløser &mdash; cron-jobben holder styr på hva som allerede er sendt, så du slipper duplikater.',
            'col_scope' => 'Omfang',
            'col_trigger' => 'Utløser',
            'col_target' => 'Mål',
            'col_recipients' => 'Mottakere',
            'col_active' => 'Aktiv',
            'notifs_cron_note' => 'Cron-jobben som sender disse e-postene, ligger i <code>cron/sla_breach_check.php</code>. Se <code>docs/sla-cron-setup.md</code> for oppsett med Oppgaveplanlegging i Windows og cron i Linux.',
            'cron_heading' => 'Cron-aktivitet',
            'cron_refresh' => 'Oppdater',
            'cron_intro' => 'De siste <span id="slaCronRunsLimit">20</span> kjøringene av cron-jobben for bruddsjekk (CLI og HTTP). Inkluderer avviste forespørsler (mengdebegrenset, mislykket autentisering) slik at den samme fasiten dekker både mengdebegrensningen og sikkerhetsrevisjoner. Ryddes automatisk etter <strong><span id="slaCronRetentionDays">30</span> dager</strong>; minste intervall mellom vellykkede kjøringer er <strong><span id="slaCronMinInterval">30</span> s</strong> (begge kan endres i <code>system_settings</code>).',
            'col_when' => 'Når',
