        'rota_weekends' => 'Ta med helger i vaktlisten',
        'numbering' => [
            'heading' => 'Saksnummerering',
            'intro' => 'Hver sak får en referanse. Det er det folk leser opp på telefonen, skriver på et skjema og søker etter seks måneder senere, så det er verdt at det er noe en person kan si høyt. Du velger formen her.',
            'style' => 'Hvordan tallene lages',
            'style_sequential' => 'Telle oppover',
            'style_sequential_help' => 'TICKET-000001, TICKET-000002, og så videre. Lett å si, lett å gjenkjenne, og rekkefølgen forteller deg hvilken som kom først.',
            'style_random' => 'Tilfeldig',
            'style_random_help' => 'Tre bokstaver og åtte sifre, som CKQ-418-73926. Dette er det FreeITSM alltid har gjort. Ingen kan gjette hvor mange saker du har, men ingen kan lese en høyt heller.',
            'format' => 'Hvordan et nummer ser ut',
