            'scope_global' => 'Én sekvens for alt',
            'scope_per_type' => 'Hver sakstype',
            'scope_per_company' => 'Hvert selskap',
            'scope_help' => 'Å telle per sakstype gir hendelser og forespørsler sine egne talløp, som er slik de fleste store servicedesker gjør det. Hvis du teller separat, må formatet vise hvilken som er hvilken — sett inn {TYPE} eller {COMPANY} i det, ellers ville hver gruppe produsert de samme tallene.',
            'reset' => 'Start på nytt',
            'reset_never' => 'Aldri — fortsett å telle',
            'reset_yearly' => 'Hvert år',
            'reset_monthly' => 'Hver måned',
            'reset_help' => 'Bare nyttig hvis året eller måneden er del av nummeret, ellers får du duplikater. Kombiner med noe sånt som <code>INC-{YYYY}-{#####}</code>.',
            'existing_note' => '<strong>Ingenting som allerede er nummerert, endres.</strong> Eksisterende saker beholder referansen de har, og hver referanse FreeITSM noensinne har utstedt, fortsetter å fungere &mdash; også i svar på gamle e-poster. Hvis du vil at eksisterende saker også skal nummereres på nytt, finnes det et verktøy for det under. <strong>Du går ikke tom for sifre:</strong> bredden du velger er et minimum, så sak 1 000 001 blir bare ett siffer lengre i stedet for å ødelegges.',
            'saved' => 'Saksnummerering lagret.',
            'renumber_heading' => 'Nummerer eksisterende saker på nytt',
            'renumber_intro' => 'Skriver om referansen på hver eksisterende sak til ordningen over, eldste først. Mest nyttig rett etter en flytting fra et annet system, når du vil at alt skal se konsistent ut.',
            'renumber_safety' => '<strong>Gamle referanser fortsetter å fungere.</strong> Hvert nummer en sak noensinne har hatt, huskes, så et svar på en e-post som siterer det gamle, havner fortsatt på riktig sak &mdash; akkurat som når saker slås sammen. Et pensjonert nummer gis heller aldri til en annen sak. Dette er derimot ikke noe du kan angre, så se på forhåndsvisningen først.',
            'renumber_preview' => 'Forhåndsvisning',
            'renumber_go' => 'Nummerer på nytt',
            'renumber_preview_first' => 'Forhåndsvis først — knappen slås på så snart du har sett hva den vil gjøre.',
            'renumber_preview_heading' => 'Kun forhåndsvisning &mdash; ingenting er endret.',
            'renumber_done_heading' => 'Saker nummerert på nytt.',
            'renumber_summary' => '{changing} av {total} sak(er) ville blitt nummerert på nytt. {skipped} stemmer allerede.',
            'renumber_next_after' => 'Den neste nye saken ville blitt {number}.',
            'renumber_confirm_title' => 'Nummerer alle saker på nytt?',
            'renumber_confirm' => 'Dette skriver om referansen på hver eksisterende sak.

Gamle referanser fortsetter å fungere, så svar på gamle e-poster finner fortsatt riktig sak. Men tallene folk har skrevet ned, satt på skjemaer og lagret i sine egne regneark, vil ikke lenger være de som vises i FreeITSM.

Dette kan ikke angres. Fortsette?',
        ],
        'general' => [
            'system_name' => 'Systemnavn',
            'system_name_moved' => 'Systemnavnet - den første delen av hver sidetittel - settes i {link}, fordi det gjelder alle moduler.',
            'system_name_moved_link' => 'System -> Merkevare',
            'system_name_placeholder' => 'f.eks. Servicedesk saksbehandlingssystem',
            'system_name_help' => 'Vises først i hver sidetittel - navnet i nettleserfanen og i bokmerker. Tomt betyr «Service Desk».',
            'reopen_label' => 'Gjenåpning',
            'reopen_toggle' => 'Gjenåpne en lukket sak når innmelderen svarer',
            'snooze_hour_label' => 'Arbeidsdagens start',
            'snooze_hour_help' => 'Tidspunktet en sak som er satt på vent til «I morgen» eller «Neste uke», kommer tilbake. Leses i hver analytikers egen tidssone, så en servicedesk spredt over flere soner får hver sin morgen.',
            'collapse_heading' => 'Lange meldinger',
            'collapse_desc' => 'Lange e-poster begraver det du åpnet saken for å lese. Meldinger som er høyere enn grensen, forkortes med en Vis mer-lenke. Ingenting slettes — hele meldingen er alltid ett trykk unna.',
            'collapse_enabled_label' => 'Forkort lange meldinger',
            'collapse_lines_label' => 'Forkort meldinger som er høyere enn omtrent',
            'collapse_lines_help' => 'linjer. En melding så vidt over grensen får stå, så lenken ikke dukker opp for to ords skyld.',
            'collapse_newest_label' => 'Vis alltid den nyeste meldingen i sin helhet',
            'collapse_newest_help' => 'Meldingen du kom for å lese, forkortes aldri.',
            'collapse_quoted_label' => 'Forkort sitert historikk',
            'collapse_quoted_help' => 'Et kort svar med en lang sitert tråd under seg er kort etter enhver linjetelling og likevel uleselig, så sitert historikk forkortes separat.',
            'collapse_remember_label' => 'Husk hva jeg har åpnet',
            'collapse_remember_help' => 'Meldinger du utvider, forblir utvidet på denne enheten.',
            'group_older_label' => 'Fold sammen eldre meldinger',
            'group_older_help' => 'Utover antallet nedenfor foldes eldre meldinger sammen til én linje du kan åpne.',
            'group_show_label' => 'Hold så mange nye meldinger åpne',
            'flag_duplicates_label' => 'Pek ut meldinger som har kommet før',
            'flag_duplicates_help' => 'En ny sending, en dobbel levering eller en returmelding foldes sammen med en merknad. Ingenting slettes.',
            'team_folders_heading' => 'Teammapper',
            'team_folders_label' => 'Analytikere ser',
            'team_folders_all' => 'Alle team',
            'team_folders_mine' => 'Bare teamene de tilhører',
            'team_folders_help' => 'Endrer bare mappelisten - ingen mister oversikten over en sak. Et team som har saker en analytiker kan se, vises fortsatt, slik at mappene fortsatt stemmer. Administratorer ser alltid alle team.',
            'watch_heading' => 'Overvåking av saker',
            'watch_help' => 'Hva overvåkerne av en sak får beskjed om. Hver overvåkers egne varselinnstillinger gjelder fortsatt i tillegg.',
            'watch_inactive_label' => 'Når en overvåker deaktiveres',
            'watch_inactive_stop' => 'Slutt å gi dem beskjed - behold overvåkingene deres i tilfelle de kommer tilbake',
            'watch_inactive_remove' => 'Fjern dem fra alle saker de overvåker',
            'watch_inactive_help' => 'En deaktivert analytiker får aldri beskjed om noe. Slutt skjuler overvåkingene og setter dem tilbake hvis analytikeren aktiveres igjen; Fjern sletter dem når analytikeren deaktiveres. Fjerning gjelder fra det tidspunktet dette lagres.',
            'watch_event_ticket_reply_received' => 'Bestilleren svarer',
            'watch_event_ticket_note_added' => 'Et notat legges til',
            'watch_event_ticket_status_changed' => 'Statusen endres',
            'watch_event_ticket_priority_changed' => 'Prioriteten endres',
            'watch_event_ticket_assigned' => 'Saken tildeles på nytt',
            'watch_event_sla_warning' => 'Den nærmer seg SLA-målet',
            'watch_event_sla_breached' => 'Den bryter SLA-målet',
            'ai_heading' => 'AI reading aids',
            'ai_desc' => 'Optional, and off until you turn them on: unlike everything else on this page these use your own AI provider and cost money per use. The provider, model and API key are configured once on the Reply cleanup tab. Nothing an AI writes ever replaces the ticket — the conversation stays exactly where it is, in full.',
            'ai_summary_label' => 'Keep a short AI summary at the top of each ticket',
            'ai_summary_help' => 'A few lines saying where the ticket stands, written on request and kept up to date. It always shows when it was written, how much it read, and how far the conversation has moved on since. Every version is kept, so a worse summary never destroys a better one.',
            'ai_auto_label' => 'Refresh it automatically after this many new messages',
            'ai_auto_help' => '0 means never — the Refresh button is then the only way, and nothing is ever charged without somebody asking. A refresh only happens when an analyst opens the ticket, so a busy queue nobody is reading costs nothing.',
            'ai_max_label' => 'Messages to read',
            'ai_max_help' => 'How far back a summary reads. A longer ticket is read from its most recent end, and the summary says so rather than describing a beginning it never saw.',
            'ai_notes_label' => 'Let it read internal notes',
            'ai_notes_help' => 'Internal notes often hold what was actually tried. They are staff-only either way — the summary is never shown to a requester — but turn this off if notes on your desk hold things that should not leave it.',
            'ai_read_label' => 'Tilby «Les den» på en sak',
            'ai_confidential_label' => 'Konfidensielle saker og AI',
            'ai_confidential_block' => 'Send dem aldri til AI (anbefalt)',
            'ai_confidential_allow' => 'Behandle dem som alle andre saker',
            'ai_confidential_help' => 'Gjelder alle AI-funksjoner som leser en sak: sammendraget, Les den, opprydding av svar, Spør AI, sammendrag ved sammenslåing, kunnskapsartikler, kanalsammendrag, problemanalyse og war room-boten. En konfidensiell sak blir enten ikke sendt, eller - der mange saker leses samtidig - utelatt eller vist bare med nummer.',
            'ai_read_help' => 'A button that reads the whole ticket and briefs you on it: what happened, what is unresolved, and what it would do next. Asked for and read once, stored nowhere.',
            'reopen_help' => 'Gjelder uansett hvor en innmelder kommer tilbake — selvbetjeningsportalen, et svar på varslings-e-posten din, WhatsApp eller nettprat. Saken går tilbake til den første åpne statusen din. Bare saker med en status som er merket som lukket, berøres (sett hvilke det er under Statuser).',
            'location_label' => 'Sted for en ny sak',
            'location_toggle' => 'Bruk bestillerens sted',
            'location_help' => 'En ny sak starter med bestillerens sted (fra personkortet), uansett vei inn - e-post, portalen, chat, API-et. Analytikere kan endre det på saken. Senere flyttinger av bestilleren endrer ikke gamle saker.',
