        'privacy' => [
            'third_party_label' => 'Meldinger som sendes til andre enn innmelderen',
            'opt_hide' => 'Skjul dem for innmelderen',
            'opt_hide_help' => 'Meldingen og vedleggene dens vises ikke i innmelderens portal i det hele tatt. Anbefalt: de fleste går ut fra at det å videresende en sak til en leverandør er noe privat.',
            'opt_no_attachments' => 'Vis meldingen, men ikke vedleggene',
            'opt_no_attachments_help' => 'Innmelderen ser at dere kontaktet noen andre og hva som ble skrevet, men kan ikke laste ned vedlagte filer.',
            'opt_show' => 'Vis alt',
            'opt_show_help' => 'Innmelderen ser hele saken nøyaktig slik analytikerne gjør, inkludert videresendinger og svar fra tredjeparter. Dette var oppførselen før denne innstillingen fantes.',
            'always_visible_note' => '<strong>Alltid synlig for innmelderen:</strong> deres egne meldinger, og alle svar som er adressert til dem. <strong>Aldri synlig:</strong> interne notater — de er skjult i portalen uansett hva denne innstillingen står på. Meldinger på WhatsApp og nettprat vises alltid, fordi de samtalene per definisjon er mellom innmelderen og servicedesken deres.',
            'timezone' => 'Tidssone',
