        'reply_cleanup' => [
            'intro1' => 'Når en analytiker skriver et grovt svar i skrivevinduet på saken, skriver knappen <strong>✨ Rydd opp</strong> det om til en ordentlig formatert e-post — den legger til en «Hei [navn],»-hilsen, retter grammatikken, bruker tonen du velger nedenfor, og avslutter med «Med vennlig hilsen,». Den vil <strong>ikke</strong> finne på tekniske detaljer eller fylle på med tomt innhold.',
            'intro2' => 'Denne funksjonen bruker sin egen Anthropic API-nøkkel (atskilt fra RFP-KI og kunnskaps-KI), slik at bruken vises som en egen linje i faktureringsoversikten hos Anthropic.',
