            'custom_placeholder' => 'f.eks. Avslutt alltid med \'Tusen takk,\'&#10;Omtal firmaet som \'BillCorp\'&#10;Bruk konsekvent bokmål',
            'custom_help' => 'Legges til systeminstruksjonen som vises til høyre. Bruk dette til tilpasninger for din organisasjon (varianter av avslutningshilsen, firmanavn, språkpreferanser). De harde sikkerhetsreglene og utdataformatet går fortsatt foran.',
            'prompt_summary' => 'Vis systeminstruksjonen (skrivebeskyttet)',
