        'csat_tab' => [
            'intro1' => 'Når en sak lukkes, sendes innmelderen en kort undersøkelse på e-post der de bes vurdere opplevelsen fra 1 til 5. Svarene registreres på analytikeren som lukket saken, slik at du kan hente ut KTI-trender per analytiker, og de vises som et element på oversiktssiden.',
            'intro2' => 'E-posten med undersøkelsen settes opp under <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">E-postmaler</a> &mdash; opprett en mal med hendelsen <strong>KTI-undersøkelse</strong>, og legg <code>[csat_link]</code> inn i brødteksten for å sette inn engangslenken til vurderingen.',
            'mode_off' => 'Av',
            'mode_off_help' => 'Det sendes ingen e-poster med undersøkelser.',
            'mode_auto' => 'Automatisk ved lukking',
            'mode_auto_help' => 'En undersøkelse sendes automatisk når en sak går over i en lukket status.',
            'mode_manual' => 'Bare manuelt',
            'mode_manual_help' => 'Analytikere klikker <em>Tilbakemelding</em> i verktøylinjen på saken når de vil spørre.',
            'delay_help' => 'Vent så mange minutter etter lukking før sending. <code>0</code> = med én gang. Nyttig hvis du vil at brukeren skal få bekreftet at løsningen faktisk holdt, før de blir bedt om å vurdere den.',
            'reminder' => 'Send én påminnelse hvis undersøkelsen ikke er besvart',
            'reminder_hours' => 'Påminn etter (timer)',
            'reminder_help' => 'Én påminnelse på det meste, på e-post, med samme lenke - så begge e-postene fungerer og bare én vurdering beholdes. Bare undersøkelser sendt på e-post får påminnelse, enten de gikk ved lukking eller fra <strong>Tilbakemelding</strong>-knappen. Sendes ikke hvis saken er åpnet igjen eller ligger i papirkurven når påminnelsen forfaller. Bruker e-postmalen <strong>KTI-påminnelse</strong> hvis du har en, ellers undersøkelsesmalen igjen. Sendes av bakgrunnsjobben <em>Forsinkede tilfredshetsundersøkelser og påminnelser</em>. Å slå dette på gir ikke påminnelse om gamle undersøkelser: bare de hvor påminnelsen forfaller fra nå av.',
            'one_per_ticket' => 'Én undersøkelse per sak',
            'one_per_ticket_help' => 'Er den på, får en sak som gjenåpnes og lukkes igjen, bare en ny undersøkelse når en analytiker utløser den manuelt &mdash; det hindrer at en ustabil sak spammer med undersøkelser.',
            'in_channel' => 'Spør chatkunder i chatten deres',
            'in_channel_help' => 'En kunde som tok kontakt på WhatsApp, Telegram, Slack, Teams eller Mattermost, blir spurt i den chatten &mdash; med knapper der appen har dem, &ldquo;svar 1 til 5&rdquo; der den ikke har det &mdash; i stedet for på e-post. WhatsApp bare mens 24-timersvinduet er åpent; ellers, og hvis en chatmelding mislykkes, brukes e-postundersøkelsen.',
            'scale_stars' => 'Stjerner',
            'scale_emojis' => 'Emojier',
            'scale_help' => 'Begge alternativene lagrer det samme tallet fra 1 til 5, så oversikter og gjennomsnitt virker likt uansett &mdash; dette endrer bare hvordan selve undersøkelsessiden ser ut.',
