    'help' => [
        'case' => [
            'nav' => 'Saksrapporter',
            'heading' => 'Saksrapporter',
            'intro' => 'Når en gjennomgang eller en revisor spør hvordan en sak ble håndtert, samler <strong>Eksporter</strong> saken, samtalen og oppgavene som gjorde jobben i ett utskriftsklart dokument - så ingen må kopiere det ut for hånd.',
            'step1' => '<strong>Åpne saken</strong> og velg <strong>Eksporter</strong> i verktøylinjen (under <strong>Mer</strong> når leseruten er smal). Rapporten åpnes i en ny fane. For en oppgave uten sak bruker du dokumentknappen øverst i oppgavevinduet i stedet.',
            'step2' => '<strong>Kryss av for det som skal med</strong> i panelet til venstre. Rapporten tegnes på nytt mens du krysser av, og ingenting registreres mens du velger.',
            'step3' => '<strong>Velg oppsett</strong>: forside, innholdsfortegnelse, hver seksjon på en ny side, og topptekst med sidetall.',
            'step4' => '<strong>Skriv ut</strong>, og velg deretter <em>Lagre som PDF</em> i utskriftsdialogen. Fjern krysset for nettleserens egne <em>Topp- og bunntekster</em> - rapporten skriver ut sine egne.',
            'contents' => '<strong>Hva som tas med:</strong> en oversikt over saken (med egendefinerte felter, koblede ressurser, konfigurasjonselementer og relaterte saker); alle meldinger, eldste først; notatene; sakens sjekklister; hver koblet oppgave med deloppgaver, sjekklisteresultater og unntaksnotater, skjemasvar, prosedyrene som ble fulgt, oppfølginger og kommentarer; historikken til saken og til hver oppgave; og en oversikt over dokumentene og e-postvedleggene, med fingeravtrykket FreeITSM har registrert for hvert dokument.',
            'layout' => '<strong>Oppsett:</strong> innholdsfortegnelsen viser alle seksjoner og oppgaver, og hver oppføring er en lenke i den lagrede PDF-en. Topptekst og sidetall (<em>Side 3 av 12</em>) krever en oppdatert Chrome eller Edge; andre nettlesere skriver ut rapporten uten dem.',
            'who' => '<strong>Hvem ser hva:</strong> rapporten viser bare det du kunne se på skjermen. Oppgaver, ressurser, konfigurasjonselementer, relaterte saker, dokumenter og skjemasvar kontrolleres hver med sin egen regel, og alt du ikke har lov til å se blir <em>talt</em> - aldri navngitt - slik at leseren vet at noe er utelatt. <strong>Interne notater utelates med mindre du krysser dem av</strong>, fordi en rapport som regel forlater teamet.',
            'recorded' => '<strong>Hva som registreres:</strong> utskrift skriver en <em>Saksrapport</em>-linje i sakens revisjonsspor med hvem som skrev den ut og hvilke seksjoner den dekket. Forhåndsvisning og endring av valgene registrerer ingenting.',
            'note' => 'En saksrapport er en kopi av journalen, ikke en fremstilling: ingenting omformuleres eller oppsummeres, bilder inne i e-poster gjengis ikke, filer listes opp i stedet for å tas med, og bare historikk FreeITSM faktisk har registrert vises. En seksjon som ikke kan leses, sier fra om det i rødt i stedet for å se tom ut.',
        ],
        'workspace' => [
            'nav' => 'Arbeidsflate og saktabell',
            'heading' => 'Arbeidsflaten og saktabellen',
            'intro' => 'To andre måter å jobbe seg gjennom saker på, begge valgfrie. <strong>Arbeidsflaten</strong> legger en sak opp for arbeid snarere enn lesing. <strong>Saktabellen</strong> viser saklisten som en tabell du kan filtrere, sortere og lagre.',
            'ws_title' => 'Arbeidsflaten',
            'ws_what' => 'I arbeidsflaten ligger sakens egenskaper i en kolonne til venstre, og <strong>Samtale</strong>, <strong>Arbeid</strong> (sjekklister, skjemaer og koblede oppgaver), <strong>Lenker</strong>, <strong>Tid og SLA</strong> og <strong>Historikk</strong> er faner ved siden av. Verktøylinjen og alle kontrollene er de samme som i leseruten - det er bare plasseringen som endres. Sakens egen <strong>sjekkliste</strong> viser alle trinn med avkrysningsboks på fanen Arbeid; <strong>Skjul</strong> viser bare neste trinn (husket i nettleseren din), og <strong>Åpne i eget vindu</strong> åpner den fortsatt for seg selv.',
            'ws_admin' => '<strong>En administrator slår den på</strong> under <strong>Saker &rarr; Innstillinger &rarr; Generelt &rarr; Saksarbeidsflate</strong>: <em>Av</em> (standard), <em>Bare saker gjort om til arbeidsflate</em> eller <em>Alle saker</em>.',
            'ws_make' => '<strong>Gjøre en sak om til arbeidsflate:</strong> i den midterste innstillingen åpner du saken og velger <strong>Mer &rarr; Lag arbeidsflate</strong> (og <strong>Tilbake til leseruten</strong> for å angre). Det hører til saken, så alle som jobber med den ser den på samme måte, og det registreres i sakens historikk.',
            'ws_own' => '<strong>Ditt eget valg:</strong> når den er på, slår <strong>Bruk arbeidsflaten</strong> i listens filtermeny, eller i <strong>System &rarr; Preferanser</strong>, den av bare for deg. En sak som er gjort om til arbeidsflate viser da et lite <em>Arbeidsflate</em>-merke, så du vet at en kollega jobber med den på den måten.',
            'ws_checklist' => '<strong>Sakens sjekklister viser alle trinn:</strong> på fanen <strong>Arbeid</strong> viser en sjekkliste alle trinnene sine med avkrysningsbokser. <strong>Skjul</strong> krymper den til bare neste trinn, slik leseruten viser den, og <strong>Utvid</strong> henter tilbake resten - nettleseren husker hva du valgte. <strong>Åpne i eget vindu</strong> åpner fortsatt hele sjekklisten i et vindu.',
            'ws_tasks' => '<strong>Koblede oppgaver åpnes på stedet:</strong> klikk på en oppgave på fanen <strong>Arbeid</strong>, så åpnes oppgavens eget redigeringsvindu der - med sjekklister, skjemaer, prosedyrer, deloppgaver, kommentarer og dokumenter. <strong>Åpne separat</strong> åpner den i et eget vindu som før; Ctrl-klikk gjør det samme. Du trenger tilgang til Oppgaver for å redigere den.',
            'ws_safe' => '<strong>Ingenting halvskrevet går tapt:</strong> hvis du går til en annen sak, eller slår av arbeidsflaten, med et svar, et notat eller en oppgaveendring som ikke er lagret, blir du spurt først, og det ventes på alt som fortsatt lagres.',
            'tb_title' => 'Saktabellen',
            'tb_what' => 'Velg <strong>Tabell</strong> i stedet for <strong>Meldinger</strong> i handlingsraden øverst i Saker (eller i <strong>System &rarr; Preferanser</strong>). Mappen du er i, blir tabellens filter; velg kolonner, filtrer og sorter dem, søk, og bla gjennom listen 25, 50 eller 100 saker om gangen. <strong>Lagre visning</strong> beholder et oppsett for deg selv, teamet ditt eller alle.',
            'tb_remember' => 'Tabellen husker visningen du sist valgte og åpner med den neste gang, i alle nettlesere - helt til du velger en annen eller bruker <strong>Tilbakestill</strong>, og da åpnes den igjen med standardvisningen din. Når den åpnes fra en mappe som allerede avgrenser listen - en avdeling, et team, en analytiker, en status eller Ikke tildelt - vinner mappen, og bare en standardvisning erstatter den.',
            'tb_same' => 'Klikking, Ctrl- og Shift-klikking, høyreklikking, dra til en mappe og masseendringene fungerer som i meldingslisten, og tabellen viser aldri en sak som listen ikke ville vist.',
            'tb_export' => '<strong>CSV-eksport:</strong> CSV-knappen eksporterer <em>alle</em> saker som samsvarer, ikke bare siden, med kolonnene du har synlige. Hvem som kan bruke den, settes under <strong>Saker &rarr; Innstillinger &rarr; Generelt &rarr; Hvem kan eksportere saklisten</strong>: bare administratorer (standard), alle med Saker, eller ingen. Knappen vises ikke for noen den ikke er åpen for.',
            'tb_columns' => '<strong>Hvem en sak gjelder:</strong> kolonnene <strong>Bestiller</strong> og <strong>Bestillers e-post</strong> viser personen saken ble opprettet for og e-postadressen deres. De er skjult til du krysser dem av under <strong>Kolonner</strong>; begge kan sorteres, og begge tas med i CSV-eksporten når de vises.',
        ],
        'page_title' => 'Servicedesk - Veiledning for saker',
        'sidebar_title' => 'Veiledning',
        'hero_title' => 'Veiledning for saksmodulen',
        'hero_sub' => 'Registrer, følg opp og løs IT-henvendelser fra én mappebasert innboks &mdash; laget for servicedeskteam.',
        'nav' => [
            'overview' => 'Oversikt',
            'inbox' => 'Innboksen',
            'working_with_tickets' => 'Arbeid med saker',
            'working_faster' => 'Jobb raskere',
            'comments_attachments' => 'Kommentarer &amp; vedlegg',
            'ai_tools' => 'KI-verktøy',
            'csat' => 'KTI-undersøkelser',
            'user_management' => 'Brukerhåndtering',
            'dashboard' => 'Oversikt',
            'calendar_rota' => 'Kalender &amp; vaktliste',
            'settings' => 'Innstillinger',
            'tips' => 'Raske tips',
            'companies' => 'Firmaer',
        ],
        'overview' => [
            'heading' => 'Oversikt',
            'intro' => 'Saksmodulen er kjernen i IT-servicedesken din. Den gir et kjent grensesnitt i stil med et e-postprogram for å håndtere henvendelser, hendelser og tjenesteoppgaver. Saker kommer inn fra sluttbrukere via e-post eller opprettes manuelt, og analytikere jobber seg gjennom dem ved hjelp av mapper, prioriteter og SLA-klokker &mdash; alt du trenger for å levere rask IT-støtte.',
            'card_inbox_title' => 'Innboks',
            'card_inbox_body' => 'En mappebasert innboks modellert på et e-postprogram. Bla gjennom mappene Mine saker, Ikke tildelt, Alle åpne og Lukkede. Klikk en sak for å åpne et lesefelt med alle detaljer, historikk og handlinger.',
            'card_dashboard_title' => 'Oversikt',
            'card_dashboard_body' => 'Bygg en personlig oversikt med tilpassbare Chart.js-elementer. Visualiser saksmengder, responstider, fordeling på kategorier og arbeidsmengde per analytikere med stolpe-, kake-, smultring- og linjediagrammer.',
            'card_calendar_title' => 'Kalender',
            'card_calendar_body' => 'Se saker i et kalenderrutenett ut fra når de ble opprettet, forfaller eller ble løst. Oppdag forfalte saker raskt og planlegg uken ved å se hele saksbildet på én gang.',
            'card_rota_title' => 'Vaktliste',
            'card_rota_body' => 'Planlegg analytikerskift og beredskapsvakter. Se hvem som er tilgjengelig når, planlegg dekning for helger og helligdager, og sørg for at ingen sak blir liggende.',
        ],
        'inbox' => [
            'heading' => 'Innboksen',
            'intro' => 'Innboksen er hovedarbeidsflaten for analytikere. Den bruker en oppdeling i tre felt &mdash; mapper til venstre, saksliste i midten og et lesefelt til høyre &mdash; slik at du kan triagere og svare uten å forlate siden.',
            'p_live' => '<strong>Den holder seg selv oppdatert.</strong> Hvert minutt sjekker innboksen postkassene dine og ser etter nytt på sakene du kan se &mdash; en e-post hentet i bakgrunnen, en melding på WhatsApp, Telegram, Slack, Teams eller Mattermost, et svar fra en kollega &mdash; og når noe har kommet, oppdateres listen og mappetellerne av seg selv, akkurat som med oppdateringsknappen. Saken du leser og et svar du skriver, blir ikke berørt.',
            'p_folders' => 'Mappepanelet organiserer saker i logiske grupper. Hver mappe viser et antall uleste, så du får øye på nytt arbeid med én gang:',
            'field_my' => '<strong>Mine saker</strong> &mdash; saker som er tildelt deg. Dette er din personlige kø og det beste stedet å starte dagen.',
            'field_unassigned' => '<strong>Ikke tildelt</strong> &mdash; saker som har kommet inn, men som ennå ikke har en analytiker. Plukk saker herfra for å ta eierskap.',
            'field_all_open' => '<strong>Alle åpne</strong> &mdash; alle saker som ennå ikke er lukket, uansett hvem som eier dem. Nyttig for ledere og teamledere som følger med på den samlede mengden.',
            'field_closed' => '<strong>Lukkede</strong> &mdash; løste saker. Søk her når du trenger å slå opp en tidligere løsning eller gjenåpne en sak.',
            'field_dept' => '<strong>Avdelingsmapper</strong> &mdash; saker gruppert etter avdeling (for eksempel IT, HR, økonomi). Avdelinger settes opp i Innstillinger og dukker opp som undermapper automatisk.',
            'switch_heading' => '<strong>Bytte mellom gruppering på avdeling og på analytiker</strong>',
            'switch_body' => 'En liten tokknappsbryter øverst i mappepanelet bytter mellom to visninger av de samme dataene. Gruppering på <strong>avdeling</strong> (standard) lister saker under hver avdeling med statusundermapper inni; gruppering på <strong>analytiker</strong> snur det, slik at hver toppmappe er den personlige køen til en analytiker, med statusundermapper inni. Mappen <strong>Ikke tildelt</strong> tilpasser seg hver visning &mdash; i avdelingsvisningen lister den saker uten avdeling, i analytikervisningen saker uten tildelt analytiker &mdash; så du ser alltid hva som må plukkes opp. Valget ditt lagres per analytiker, så hvert teammedlem beholder visningen de foretrekker fra gang til gang.',
            'folders_hide' => '<strong>Trenger du mer plass?</strong> Trykk <strong>[</strong> (når du ikke skriver), eller <strong>&laquo;</strong> øverst i mappepanelet, for å brette det sammen til en tynn stripe; trykk <strong>[</strong> eller klikk på stripen for å hente det tilbake. For å ha det sammenbrettet hver gang velger du <strong>Klikk for å åpne</strong> eller <strong>Vis ved peking</strong> for <em>Saker - mapper</em> i Preferanser &rarr; Visning &rarr; Venstre paneler. Når mappene er sammenbrettet, åpnes de over saklisten og lukkes igjen når du velger en. På en telefon fungerer mappene som før.',
            'folders_narrow' => '<strong>I et smalt vindu</strong> (1100 px bredt eller mindre, for eksempel et nettbrett) starter mappene sammenbrettet selv med <strong>Alltid synlig</strong>, og saklisten blir litt smalere, så saken du leser får plass. Gjør vinduet bredere, så kommer de tilbake.',
            'p_actions' => 'Over saklisten har du fire handlingsknapper: <strong>Ny</strong> for å opprette en sak, <strong>Søk</strong> for å finne saker etter nøkkelord, referanse eller bestiller, <strong>Filter</strong> for å begrense det du ser, og <strong>Oppdater</strong> for å laste gjeldende mappe på nytt.',
            'filter_body' => 'Knappen <strong>Filter</strong> (traktsymbolet) begrenser mappene og listen samtidig, uansett hvordan de er gruppert. <strong>Mine</strong> viser bare saker som er tildelt deg, og <strong>Skjul lukkede</strong> utelater alle saker med en status som er merket som lukket. Mens et filter er på, har traktsymbolet en prikk og en etikett vises ved siden av listetittelen, så du alltid vet at du ikke ser alt. Når mappene er gruppert etter <strong>Analytiker</strong>, ligger din egen mappe øverst som <strong>Mine saker</strong> i stedet. Søk har sin egen bryter, <strong>Ta med lukkede saker</strong>, som er på som standard, fordi et søk som regel er jakt på en gammel sak. Begge valgene lagres bare for deg.',
            'row_name' => 'Hver rad viser saksreferansen og deretter et navn. Som standard er det <strong>personen som meldte saken</strong>, og det er det samme gjennom hele sakens levetid. Hvis du heller vil se hvem som sendte den siste meldingen &mdash; som blir din egen postkasse når du har svart &mdash; endrer du <strong>Navn ved siden av saksnummeret</strong> under <strong>Innstillinger &rarr; Radvisning</strong>, der du også kan skjule navnet og bare vise referansen. Den fanen er din egen innstilling: den endrer ingenting for andre.',
            'tip' => 'Klikk en sak i listen for å laste den i lesefeltet. Derfra kan du oppdatere felt, legge til kommentarer, svare på e-post eller legge ved filer &mdash; alt uten å navigere bort fra innboksen.',
        ],
        'live' => [
            'heading' => 'Direkteoppdateringer',
            'body' => 'FreeITSM holder skjermen din i takt med alle andre. Når en kollega endrer en sak - status, prioritet, eier eller team, et svar, et notat - henger saklisten og saken du har åpen med innen omtrent 15 sekunder, uten at du trykker på oppdater. Oppgavetavlen, en åpen oppgave og bjella fungerer på samme måte.',
            'what' => 'Den sjekker bare mens fanen er foran deg, og henger med i det øyeblikket du kommer tilbake til den. En endring du gjør i én fane vises straks i de andre fanene dine.',
            'safe' => 'Den kaster aldri bort det du holder på med. Mens du skriver et svar eller et notat, skriver i et felt eller har en meny åpen, dukker nye meldinger fortsatt opp i samtalen, og resten venter bak en liten melding: <strong>Oppdatert av noen andre akkurat nå &middot; Oppdater</strong>.',
            'setting' => '<strong>Preferanser &rarr; Direkteoppdateringer</strong> velger hvert 15. sekund (standard), 30 sekunder, hvert minutt, eller av.',
        ],
        'watch' => [
            'heading' => 'Følge en sak',
            'body' => 'Følg en sak uten å eie den - en teamleder som holder øye med en større hendelse, eller analytikeren som ga den videre. Følgere får beskjed om saken som om den var deres, gjennom egne varslingsinnstillinger.',
            'how' => '<strong>Følg</strong> i sakens verktøylinje, eller høyreklikk den i listen og velg <strong>Følg</strong>. Høyreklikk et utvalg for å følge alle. På en sak du allerede følger, står det <strong>Slutt å følge</strong> på verktøylinjeknappen og i høyreklikkmenyen i stedet - et utvalg kan følges, men ikke slutte å følges i ett grep.',
            'others' => '<strong>Følg</strong>-knappen viser hvem som følger. Med skrivetilgang til Saker kan du <strong>legge til en kollega</strong> eller fjerne noen; alle kan fjerne seg selv.',
            'what' => '<strong>Saker &rarr; Innstillinger &rarr; Generelt &rarr; Følge saker</strong> velger hva følgere får høre om - svar, notater, status, prioritet, omtildeling, SLA-advarsler og brudd - alt sammen med mindre en administrator fjerner krysset for noe. En omtildeling når en følger som «omtildelt», aldri «tildelt deg», og den har en egen bryter i hver persons preferanser.',
            'leaver' => 'En deaktivert analytiker får aldri beskjed om en sak de følger. <strong>Saker &rarr; Innstillinger &rarr; Generelt &rarr; Når en følger deaktiveres</strong> avgjør hva som skjer med følgingene deres: <strong>Stopp</strong> (standard) holder dem ute av syne og setter dem tilbake hvis analytikeren gjøres aktiv igjen; <strong>Fjern</strong> tar analytikeren av alle saker de følger når de deaktiveres.',
            'note' => 'Bare personer som kan se en sak, kan følge den, og hvis de slutter å kunne se den, slutter de å høre om den. Ingen får beskjed om sin egen endring. Sammenslåing flytter følgere til saken som blir igjen.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Skjemaer på en sak',
            'body' => 'Legg ved et skjema fra Skjema-modulen til en sak og fyll det ut der - en forespørsel om ny ansatt som trenger utstyrsskjemaet sitt, eller en sikkerhetshendelse som trenger rapporten sin. Svarene beholdes sammen med saken.',
            'switch' => '<strong>Saker &rarr; Innstillinger &rarr; Sjekklister &rarr; Skjemaer på saker</strong> slår det på (det er av til du gjør det, og Skjema-modulen må også være på). En <strong>Skjemaer</strong>-knapp vises da i hver sak sin verktøylinje, med antall innsendte. I en arbeidsflate vises skjemaene også på fanen <strong>Arbeid</strong>. Høyreklikk en sak, eller et utvalg, og velg <strong>Legg til skjema</strong> for å legge til et uten å åpne saken.',
            'how' => '<strong>Skjemaer</strong> åpner listen: <strong>Legg til</strong> velger et skjema (alltid den nyeste versjonen), <strong>Fyll ut</strong> åpner det i et vindu, <strong>Lagre utkast</strong> beholder halvferdige svar som kolleger kan fortsette på, og <strong>Korriger</strong> erstatter en innsending mens den gamle beholdes i Skjemaer.',
            'required' => 'Hvert skjema er <strong>Påkrevd - hindrer lukking</strong>, <strong>Påkrevd - advarer ved lukking</strong> eller <strong>Valgfritt</strong>. Et skjema som hindrer lukking, må sendes inn før saken kan nå en lukket status; et som advarer, spør og registrerer hvem som lukket den likevel.',
            'note' => 'Å fylle ut et skjema krever skrivetilgang til Skjemaer og til Saker. Å lese svarene krever tilgang til Skjemaer eller tillatelsen <strong>Les skjemasvar på saker du kan se</strong> (en rolleinnstilling); alle andre ser hvem som sendte det inn og når, men ikke hva de sa. En innsending som en sak er avhengig av, kan ikke slettes fra Skjemaer. Svar vises i sakens saksrapport og i REST API.',
        ],
        'faster' => [
            'heading' => 'Jobb raskere',
            'intro' => 'Fire ting som gjør en travel morgen håndterbar: lagrede svar, å handle på mange saker på én gang, og å legge samtaler der de hører hjemme.',
            'templates_heading' => 'Standardsvar',
            'templates_body' => 'Du sender de samme svarene hele tiden. Skriv ett én gang, og klikk deretter <strong>Maler</strong> nederst til venstre i svarvinduet for å sette det inn ved markøren &mdash; det legges til det du allerede har skrevet i stedet for å erstatte det. Maler er rik tekst og støtter de samme <code>[merge_code]</code>-plassholderne som de automatiske e-postene, så <code>[requester_first_name]</code> blir det ekte navnet idet du setter inn malen.',
            'templates_team' => '<strong>Teammaler</strong> &mdash; delt med alle, settes opp under Innstillinger &rarr; Svarmaler.',
            'templates_mine' => '<strong>Dine egne</strong> &mdash; lagre et utkast med <em>Lagre utkastet som mal</em>. Privat for deg, og ingen tillatelse er nødvendig.',
            'templates_tip' => 'Gi en mal navn etter situasjonen («Skriver frakoblet &mdash; første steg»), ikke etter ordlyden. Det er det du kommer til å lete etter klokken ni om morgenen.',
            'select_heading' => 'Velge flere saker',
            'select_body' => 'Sakslisten virker som Outlook eller Filutforsker. Ingen avkrysningsbokser.',
            'key_click' => 'Klikk',
            'key_click_d' => 'velg én og åpne den',
            'key_ctrl' => 'Ctrl+klikk',
            'key_ctrl_d' => 'legg til eller fjern én, la resten være',
            'key_shift' => 'Shift+klikk',
            'key_shift_d' => 'velg en hel blokk fra der du sist klikket',
            'key_kb' => 'Tastatur',
            'key_kb_d' => 'piltaster for å flytte, Shift+piltaster for å utvide, Ctrl+piltaster og mellomrom for å plukke ut spredte saker, Ctrl+A for alt, Escape for å nullstille',
            'select_actions' => 'Med flere valgt kan du <strong>høyreklikke en av dem</strong> for å sette status, prioritet, avdeling, type eller tildelt analytiker på alle sammen på én gang &mdash; eller dra hele settet inn i en mappe. Hva skjermen viser mens flere er valgt, bestemmer du selv, i kontomenyen under Innstillinger.',
            'select_tip' => 'Høyreklikker du en sak som <em>ikke</em> er i utvalget ditt, nullstilles utvalget og bare den ene saken treffes. Det er med vilje &mdash; du kan aldri handle på et utvalg du trodde du var ferdig med.',
            'merge_heading' => 'Slå sammen duplikater',
            'merge_body' => 'Meldte to personer det samme avbruddet? Velg sakene, høyreklikk, <strong>Slå sammen</strong>. Samtalene samles, og har du satt opp en KI-leverandør, skriver FreeITSM en kort oppsummering av hva alle spurte om og hva som allerede er gjort, slik at den som tar over, slipper å lese fire tråder.',
            'merge_tip' => 'Ingenting slettes noen gang. Saken som ble slått sammen inn, beholder referansen sin, forblir søkbar og viser hvor den ble av &mdash; og en kunde som svarer på en gammel e-post om den, når fortsatt fram til deg.',
            'split_heading' => 'Dele opp en sak',
            'split_body' => 'Den motsatte jobben. Når noen tar opp en ny, urelatert ting midt i en samtale, klikker du <strong>Del opp</strong> på den meldingen (eller høyreklikker meldingsoverskriften). Den flyttes til en ny sak, eventuelt med alle nyere meldinger med seg, og den opprinnelige beholder en markør som viser hvor de ble av.',
            'split_tip' => 'Gi den nye saken et ordentlig emne. Standarden er emnet til den flyttede meldingen, som regel et «SV:» på det <em>gamle</em> problemet.',
            'undo_heading' => 'Ombestemt deg',
            'undo_body' => 'Begge deler kan angres fra banneret på saken. Å angre en <strong>oppdeling</strong> avvises når noen har svart på den nye saken, lagt til et notat eller ført tid &mdash; du får nøyaktig beskjed om hva som står i veien. Å angre en <strong>sammenslåing</strong> gir saken tilbake meldingene, notatene og den førte tiden sin og gjenåpner den nøyaktig slik den var, men svar som er skrevet på den andre saken etter sammenslåingen, blir værende der.',
        ],
        'working' => [
            'heading' => 'Arbeid med saker',
            'intro' => 'Hver henvendelse følger en livssyklus: den opprettes, triageres, jobbes med og løses til slutt. Saksmodulen gir deg verktøyene til å håndtere hvert trinn effektivt, fra første registrering til lukking.',
            'creating_heading' => '<strong>Opprette en ny sak</strong>',
            'step1' => '<strong>Klikk Ny</strong> &mdash; åpne vinduet for ny sak fra verktøylinjen i innboksen. Fyll inn navnet og e-postadressen til innmelderen, slik at de kan få oppdateringer.',
            'step2' => '<strong>Sett emnet</strong> &mdash; skriv en tydelig og kortfattet oppsummering av problemet. Dette vises i sakslisten og i eventuelle e-postvarsler som sendes til sluttbrukeren.',
            'step3' => '<strong>Velg avdeling, type og prioritet</strong> &mdash; velg riktig avdeling, sakstype (for eksempel hendelse eller tjenesteforespørsel) og prioritetsnivå. Disse feltene styrer SLA-klokker og rutingsregler.',
            'step4' => '<strong>Legg til beskrivelsen</strong> &mdash; gi alle detaljer om problemet i rik-tekst-editoren. Ta med hvordan det kan gjenskapes, feilmeldinger og annen relevant sammenheng den som skal løse saken, trenger.',
            'step5' => '<strong>Lagre</strong> &mdash; saken opprettes med et unikt referansenummer og dukker opp i riktig mappe. SLA-klokken starter umiddelbart ut fra prioriteten.',
            'editing_heading' => '<strong>Redigere og håndtere saker</strong>',
            'editing_body' => 'Når en sak først finnes, kan du oppdatere alle felt fra lesefeltet. Viktige felt er blant andre:',
            'card_status_title' => 'Status',
            'card_status_body' => 'Følg saksforløpet: Ny, Åpen, Under arbeid, Venter, Løst, Lukket',
            'card_priority_title' => 'Prioritet',
            'card_priority_body' => 'Sett hastegrad og omfang: Kritisk, Høy, Middels, Lav. Hvert nivå har sitt eget SLA-mål',
            'card_category_title' => 'Kategori',
            'card_category_body' => 'Klassifiser problemtypen: Maskinvare, Programvare, Nettverk, Tilgang, Generelt. Nyttig for rapportering',
            'card_analyst_title' => 'Tildelt analytiker',
            'card_analyst_body' => 'Personen som har ansvaret for å løse saken. Ny tildeling logges i aktivitetssporet',
            'card_enduser_title' => 'Sluttbruker',
            'card_enduser_body' => 'Personen som meldte inn henvendelsen. Slå opp på navn eller e-post for å koble til et eksisterende brukerkort',
            'card_dept_title' => 'Avdeling',
            'card_dept_body' => 'Rut saker til riktig team. Avdelinger styrer mappegruppering og filtre på oversikten',
            'flow_new' => 'Ny',
            'flow_in_progress' => 'Under arbeid',
            'flow_resolved' => 'Løst',
            'flow_closed' => 'Lukket',
            'triage_heading' => '<strong>Triage med dra og slipp</strong>',
            'triage_body' => 'Du trenger ikke å åpne en sak for å triagere den. Dra en rad fra sakslisten inn i en mappe for å oppdatere felt i én bevegelse:',
            'triage_dept' => '<strong>Avdelingsvisning</strong> &mdash; slipp på en avdelingsmappe for å flytte saken dit, slipp på en statusundermappe under en avdeling for å oppdatere begge deler på én gang, slipp på <strong>Ikke tildelt</strong> for å fjerne avdelingen.',
            'triage_analyst' => '<strong>Analytikervisning</strong> &mdash; slipp på en analytikers mappe for å sette den analytikeren som eier (setter både <code>assigned_analyst_id</code> og <code>owner_id</code>, så Eier-feltet i lesefeltet holdes i takt), slipp på en statusundermappe for å oppdatere begge deler, slipp på <strong>Ikke tildelt</strong> for å fjerne tildelingen.',
            'triage_spring' => '<strong>Fjærbelastede mapper</strong> &mdash; hold musepekeren over en sammenslått mappe mens du drar, så åpnes den automatisk (som i Outlook), slik at enhver underliggende status er innen rekkevidde uten at du må slippe først.',
            'fullscreen_heading' => '<strong>Fullskjermvisning</strong>',
            'fullscreen_body' => 'Når du trenger å konsentrere deg om én enkelt sak &mdash; en lang samtale, en sammensatt endring, eller et grundig svar som skal skrives &mdash; bytter du til fullskjermvisning. Mappelisten og sakslisten forsvinner, samtalen fyller hele bredden, og egenskapene (Avdeling, Type, Status, Kilde, Løst ved første kontakt, IT-opplæring, Eier) flyttes til et loddrett sidefelt til høyre.',
            'fullscreen_max' => '<strong>Maksimer-ikonet</strong> &mdash; et lite ikon helt til høyre på emnelinjen til saken. Klikk for å gå til fullskjerm; klikk igjen for å gå tilbake til visningen med tre felt.',
            'fullscreen_dbl' => '<strong>Dobbeltklikk en rad</strong> &mdash; dobbeltklikk en sak i listen for å åpne den direkte i fullskjerm, den samme «åpne denne ordentlig»-bevegelsen som i Outlook.',
            'fullscreen_sticks' => '<strong>Blir værende mellom valg</strong> &mdash; når du først er i fullskjerm, blir du der selv om du bytter til neste sak. Laster du siden på nytt (F5) uten en valgt sak, går du tilbake til standardvisningen med tre kolonner, så du kan ikke bli sittende fast med mappelisten skjult.',
            'fullscreen_back' => '<strong>Tilbake</strong> &mdash; linjen over saken viser referansen og en <strong>Tilbake</strong>-knapp, som tar deg rett tilbake til listen akkurat slik du forlot den, med tastaturet tilbake på listen - så pilene flytter mellom saker og Enter åpner neste sak med en gang. <strong>Escape</strong> gjør det samme, når et vindu eller en meny som er åpen over saken, er lukket. Ingen av dem slår av fullskjerm: neste sak åpnes fortsatt i fullskjerm (krympeikonet er bryteren), og når du går tilbake til saken du forlot, ligger et svar du hadde begynt på fortsatt der.',
            'fullscreen_keys' => '<strong>Tastene ruller saken</strong> &mdash; i fullskjerm ruller piltastene, Page Up / Page Down og mellomrom samtalen, ikke den skjulte saklisten. I et bilde- eller PDF-vindu ruller de det vinduet. I den vanlige visningen med tre ruter klikker du i saken, så ruller tastene den også; klikk på listen for å gå tilbake til å flytte mellom saker.',
            'viewer_heading' => '<strong>Bilder og PDF-er åpnes over saken</strong>',
            'viewer_body' => 'Klikk på et bilde eller en PDF som er lagt ved et notat, eller en i sakens <strong>Vedlegg</strong>-liste (miniatyrbildet eller raden), og den åpnes i et vindu oppå saken &mdash; samme viser som i Filer-modulen. Saken blir stående akkurat der den var under.',
            'viewer_window' => '<strong>Flytt og endre størrelse</strong> &mdash; dra tittellinjen for å flytte vinduet og en hvilken som helst kant eller et hjørne for å endre størrelsen; dobbeltklikk tittellinjen, eller dra den til toppen av skjermen, for å fylle skjermen. Bildet eller PDF-en tilpasses på nytt når vinduet endrer størrelse, helt til du zoomer inn eller ut selv &mdash; <strong>Tilpass</strong> gir den tilbake. Åpne flere, så ligger de side ved side.',
            'viewer_close' => '<strong>Lukk den</strong> &mdash; &times; i tittellinjen, eller <strong>Escape</strong> (som lukker vinduet foran). <strong>Last ned</strong> lagrer filen. På en telefon åpnes filen i fullskjerm med en Tilbake-knapp.',
            'viewer_other' => '<strong>Andre filer</strong> &mdash; Word-dokumenter, regneark og alt annet lastes fortsatt ned eller åpnes i en ny fane, som før. For i stedet å åpne et notats bilde eller PDF i en ny fane, Ctrl-klikker du på det.',
            'paste_heading' => '<strong>Lim inn et skjermbilde i et notat</strong>',
            'paste_body' => 'Kopier et skjermbilde, klikk i <strong>Legg til notat</strong>-boksen og trykk <strong>Ctrl+V</strong>. Bildet settes inn der markøren er, med teksten din før og etter, og blir på det stedet når notatet er lagret. Klikk på det for å åpne det i viseren. <strong>Backspace</strong> fjerner det før du lagrer.',
            'paste_shared' => '<strong>Delte notater deler bildene sine</strong> &mdash; bestilleren ser dem i portalen, på stedet. På et internt notat er de like private som notatet.',
            'paste_save' => '<strong>Ingenting beholdes før du trykker Lagre</strong> &mdash; lukk boksen, så forsvinner bildene med den. Hvis et bilde avvises, lagres heller ikke notatet, årsaken vises, og teksten din står fortsatt i boksen.',
            'paste_text' => '<strong>Tekst forblir tekst</strong> &mdash; å lime inn fra Word, en nettside eller Excel setter inn ordene uten formateringen. <strong>Legg ved</strong>-knappen fungerer fortsatt for alle andre filer.',
            'rightclick_heading' => '<strong>Høyreklikk for raske handlinger</strong>',
            'rightclick_body' => 'Høyreklikk en sak i listen for å åpne en hurtigmeny. Menyen viser saksreferansen øverst, så du vet hva du handler på, og hver handling gjelder saken du høyreklikket, <em>uten</em> å endre det som er åpent i lesefeltet &mdash; nyttig når du leser sak A og må triagere sak B uten å miste plassen din.',
            'rightclick_status' => '<strong>Sett status &rarr;</strong> &mdash; en undermeny som lister alle aktive statuser med fargeprøven sin. Et hakemerke vises ved den gjeldende verdien hvis du høyreklikker saken du har åpen. Valget oppdaterer saken umiddelbart, skriver en oppføring i revisjonssporet, oppdaterer mappetellingene og synkroniserer statuslisten i lesefeltet der det er aktuelt.',
            'rightclick_priority' => '<strong>Sett prioritet &rarr;</strong> &mdash; samme mønster, hentet fra oppslaget over aktive prioriteter, med fargen til hver av dem som fargeprøve. Den første raden er et <em>(ingen prioritet)</em>-valg for å fjerne tildelingen (prioritet kan være tom).',
            'rightclick_assign' => '<strong>Tildel til &rarr;</strong> &mdash; en undermeny som lister alle innlastede analytikere med en grå initialbrikke, pluss en <em>(ikke tildelt)</em>-rad øverst for å fjerne tildelingen. Valget setter både <code>assigned_analyst_id</code> OG <code>owner_id</code>, så Eier-feltet i lesefeltet holdes i takt.',
            'rightclick_cmdb' => '<strong>Koble CMDB-objekt &hellip;</strong> &mdash; åpner en velger som søker mens du skriver. Klikk et treff for å koble det, og fortsett å plukke &mdash; feltet tømmes og får fokus igjen til det neste, og en «Nylig koblet»-logg inne i vinduet viser den løpende listen din med grønne hakemerker.',
            'rightclick_time' => '<strong>Før tid &hellip;</strong> &mdash; åpner et vindu med minutter + en dato- og tidsvelger (som står på «nå», så du også kan tilbakedatere) + et valgfritt notatfelt.',
            'rightclick_more' => '<strong>Legg ved sjekkliste &rarr;</strong>, <strong>Legg til skjema &rarr;</strong> og <strong>Følg</strong> - legg ved en sjekkliste (beste treff først), legg til et skjema, eller følg saken uten å åpne den. På et utvalg virker de på hver valgte sak, og hopper over de som allerede har den sjekklisten eller det skjemaet.',
            'rightclick_phone' => '<strong>På en mobil</strong> trykker og holder du på en sak i et halvt sekund for å åpne den samme menyen som et fullskjermspanel. Et valg med flere alternativer &mdash; Sett status, Sett prioritet, Tildel til &mdash; glir over til dem, med <strong>Tilbake</strong> for å gå tilbake.',
            'rightclick_tip' => 'Er saken du handler på via hurtigmenyen, tilfeldigvis den samme som er åpen i lesefeltet, oppdateres den aktuelle delen der (status- og prioritetslistene, CMDB-objektene, tidsføringene) automatisk når vinduet lukkes, slik at grensesnittet holder seg i takt.',
            'time_heading' => '<strong>Å føre tid</strong>',
            'time_body' => 'Tid brukt på en sak føres i en egen <strong>Tidsføringer</strong>-seksjon i lesefeltet, som ligger mellom panelet med koblede CMDB-objekter og notatpanelet. Overskriften viser den løpende summen (for eksempel «Totalt 2t 30m»), og hver oppføring under viser tiden som er brukt, analytikeren, datoen og eventuelle notater du la til.',
            'time_step1' => '<strong>Skjema i linjen</strong> &mdash; skriv antall minutter i tallfeltet, en valgfri kort beskrivelse i notatfeltet, og klikk <strong>Legg til</strong>. Den nye oppføringen dukker opp med én gang øverst i listen, med navnet ditt og tidspunktet nå.',
            'time_step2' => '<strong>Tilbakedater via høyreklikk</strong> &mdash; trenger du å føre tid du glemte å registrere tidligere, høyreklikker du saken i listen og velger <strong>Før tid &hellip;</strong>. Vinduet har en dato- og tidsvelger, så du kan stemple oppføringen med tidspunktet arbeidet faktisk ble gjort.',
            'time_step3' => '<strong>Slett dine egne oppføringer</strong> &mdash; en liten &times;-knapp dukker opp ved oppføringer du har ført. Klikk den (og bekreft) for å slette mykt &mdash; raden blir stående i databasen med <code>is_active = 0</code> for revisjon, men forsvinner fra listen. Du kan ikke slette andre analytikeres oppføringer.',
            'time_tip1' => 'Tider lagres som rene minutter (45 min, 90 min og så videre) og vises som <code>45m</code> eller <code>1t 30m</code> i grensesnittet &mdash; finmasket nok for korte fikser, uten avrundingskvaler med desimaltimer.',
            'time_tip2' => 'Hver feltendring registreres i aktivitetssporet til saken. Du kan alltid se hvem som endret hva og når, noe som er avgjørende for revisjonskrav og for overlevering mellom analytikere.',
        ],
        'comments' => [
            'heading' => 'Kommentarer &amp; vedlegg',
            'intro' => 'Aktivitetssporet er hjertet i hver sak. Det fanger opp hver handling som gjøres &mdash; kommentarer, feltendringer, sendte e-poster og vedlagte filer &mdash; i en tidslinje som forteller hele historien om en henvendelse.',
            'adding_heading' => '<strong>Legge til kommentarer</strong>',
            'step1' => '<strong>Åpne saken</strong> &mdash; klikk en sak i innboksen for å laste lesefeltet. Bla ned for å se hele aktivitetssporet og kommentarfeltet nederst.',
            'step2' => '<strong>Skriv notatet ditt</strong> &mdash; bruk Legg til notat-knappen for å åpne kommentareditoren. Notater er interne som standard og synlige bare for analytikere på servicedesken.',
            'step3' => '<strong>Svar eller videresend på e-post</strong> &mdash; bruk Svar- eller Videresend-handlingene for å sende en melding til sluttbrukeren eller en tredjepart. E-posten logges i aktivitetssporet sammen med innholdet i den utgående meldingen.',
            'subject_note' => '<strong>Emnet</strong> &mdash; Svar og Videresend viser emnet, og du kan endre det. Når du videresender en sak til en ekstern leverandør og svaret deres legger sitt eget nummer til emnet (for eksempel <em>#TCK89633 - FW: &hellip;</em>), bruker du <strong>Svar</strong> eller <strong>Videresend</strong> på <em>den</em> meldingen i samtalen: den starter fra emnet sitt, så oppfølgingen din beholder nummeret deres og havner på saken deres. Hver melding viser sitt eget emne under avsenderen. Sakens referanse i hakeparenteser beholdes alltid &mdash; fjerner du den, settes den tilbake når du sender, så svar fortsatt kommer tilbake til denne saken.',
            'requester_note' => '<strong>Endre bestiller</strong> &mdash; <strong>Endre bestiller</strong>, ved siden av avsenderen øverst i saken, gjør saken til noen andres: en kollega som registrerte den på vegne av noen, en feil ved mottaket. Det skrives til sakens historikk. Når den gamle bestilleren ser ut til å være den samme personen som skriver fra en annen adresse, får du tilbud om å slå dem sammen: de andre sakene deres flyttes også, og adressen deres blir en av den nye personens, så neste e-post fra dem havner der. En <strong>Bestiller</strong>-linje under avsenderen vises hver gang saken er for en annen enn personen som skrev meldingen. E-post fra en adresse som er knyttet til en person (Personer &rarr; siden deres &rarr; E-postadresser) er deres, så den lager aldri en ny person.',
            'addresses_note' => '<strong>Adresser mens du skriver</strong> &mdash; begynn å skrive i <strong>Til</strong> eller <strong>Kopi</strong>, så foreslår FreeITSM adresser: først leverandørens <strong>servicedesk</strong> (sett den på leverandøren i Kontrakter), deretter leverandørkontakter, personer i sakens selskap og adresser det nylig er sendt e-post til fra det selskapets saker. Bruk piltastene og Enter, eller klikk; velg så mange du vil, eller fortsett å skrive dine egne. En adresse fra ett selskaps saker foreslås aldri på et annet selskaps saker, og hvem en konfidensiell sak ble sendt til, foreslås aldri i det hele tatt.',
            'attachments_note' => '<strong>E-postvedlegg</strong> &mdash; i vedleggslisten åpner et klikk vedlegget i et vindu over saken der filtypen tillater det: bilder, PDF-er, Word-dokumenter, regneark og CSV-filer, tekst, lyd og video, med en nedlastingsknapp. Alt annet lastes ned. <strong>Lagre i Filer</strong> ved siden av hvert vedlegg - og ved siden av hver fil på et notat - kopierer det inn i en mappe i Filer. For å legge en fil som allerede er i Filer på saken, bruker du <strong>Fra Filer</strong> i <strong>Legg til notat</strong>-vinduet (<strong>Fra datamaskin</strong> er knappen ved siden av) - et vindu som en fildialog åpnes, med mapper til venstre og filene deres til høyre - som en lenke (åpnet gjennom Filer, under mappens tillatelser, aldri vist i portalen) eller en kopi, slik Filer &rarr; Innstillinger &rarr; Deling tillater.',
            'files_heading' => '<strong>Filvedlegg</strong>',
            'files_body' => 'Legg ved skjermbilder, logger, dokumenter eller hvilken som helst støttende fil rett på en sak. Filer kan dras inn i slippsonen for vedlegg eller velges med filutforskeren. Vedlegg lagres på serveren og kobles til aktivitetssporet til saken, så ingenting går tapt.',
            'audit_heading' => '<strong>Revisjonslogging</strong>',
            'export_heading' => '<strong>Saksrapporter</strong>',
            'export_body' => 'For en gjennomgang eller en revisor gjør <strong>Eksporter</strong> i sakens verktøylinje saken og oppgavene om til én utskriftsklar rapport - se <a href="#case-reports">Saksrapporter</a>.',
            'audit_body' => 'Aktivitetssporet registrerer hver handling automatisk, uten at analytikeren må gjøre noe. Når en prioritet endres fra Middels til Høy, fanges både den gamle og den nye verdien opp. Når en sak tildeles på nytt, logges både den forrige og den nye analytikeren. Dette gir en fullstendig historikk som ikke kan tukles med, som tilfredsstiller ITIL-krav til revisjon og hjelper ledere med å forstå hvordan saker håndteres.',
            'tip' => 'Når du svarer på e-post, kan du legge til kopimottakere og legge ved filer i den samme handlingen. Hele e-postsamtalen trådes inn i aktivitetssporet til saken, slik at all kommunikasjon holdes på ett sted.',
        ],
        'ai' => [
            'heading' => 'KI-verktøy',
            'intro' => 'To Claude-drevne funksjoner ligger inne i saksarbeidsflyten: <strong>Opprydding i svar</strong> skriver et grovt utkast om til en ordentlig formatert e-post, og <strong>Spør KI-en</strong> søker i kunnskapsbasen på naturlig språk ved hjelp av sammenhengen i saken.',
            'cleanup_heading' => '<strong>Opprydding i svar &mdash; ✨-knappen i svareditoren</strong>',
            'cleanup_body' => 'Skriv et raskt, grovt utkast i et svar (eller bare punkter som *«må starte utskriftstjenesten på nytt, ta skjermbilde til dem»*) og klikk <strong>✨ Rydd opp</strong>-knappen. Claude skriver det om til en ordentlig formatert e-post &mdash; legger til en <em>Hei [navn],</em>-hilsen fra innmelderen, retter grammatikken, bruker den innstilte tonen og avslutter med <em>Med vennlig hilsen,</em>. Instruksjonen er strammet inn, så den vil IKKE finne på tekniske detaljer, dikte opp unnskyldninger eller fylle på med mer enn det du skrev.',
            'cleanup_streams' => '<strong>Strømmer direkte</strong> &mdash; omskrivingen dukker opp i editoren etter hvert som Claude lager den (ingen venting foran en snurrende sirkel).',
            'cleanup_undo' => '<strong>Angre-lenke i 30 s</strong> &mdash; i tilfelle Claude ødelegger omskrivingen, dukker en liten <em>Angre</em>-lenke opp under editoren i 30 sekunder etter at omskrivingen er ferdig, og gjenoppretter det opprinnelige utkastet.',
            'cleanup_tone' => '<strong>Per tone</strong> &mdash; tre forhåndsinnstilte toner som settes opp under <strong>Innstillinger &rarr; Opprydding i svar</strong>: <em>Vennlig</em> (standard), <em>Formell</em>, <em>Kortfattet</em>. Velg den som passer husstilen til teamet ditt.',
            'cleanup_key' => '<strong>Egen API-nøkkel</strong> &mdash; en Anthropic-nøkkel atskilt fra KI-funksjonene for RFP, kunnskap og arbeidsflyt, slik at bruken vises som sin egen linje i faktureringsoversikten hos Anthropic. Settes opp under <strong>Innstillinger &rarr; Opprydding i svar</strong>.',
            'cleanup_prompt' => '<strong>Din egen prompt</strong> &mdash; <em>Saker &rarr; Innstillinger &rarr; Svaroppryddingen</em> viser systemprompten, og du kan endre den. Hver lagrede versjon beholdes under <em>Historikk</em>: <em>Gjenopprett</em> setter en tidligere tilbake, og <em>Tilbakestill</em> går tilbake til den innebygde prompten.',
            'cleanup_tip' => 'Opprydding passer best til de rutinemessige svarene i stil med «jeg prøvde dette, prøv X». Lange og nyanserte meldinger vil du skrive selv &mdash; KI-en er god på struktur, men kjenner ikke ditt spesifikke miljø.',
            'ask_heading' => '<strong>Spør KI-en &mdash; 🤖-knappen i verktøylinjen på saken</strong>',
            'ask_body' => 'Klikk <strong>Spør KI-en</strong>-knappen (🤖) i verktøylinjen på saken for å åpne et pratepanel som glir inn og som kjenner emnet, teksten og sammenhengen i lesefeltet på den åpne saken. Still spørsmål som *«har vi sett dette før?»* eller *«hva er den vanlige løsningen på denne feilen?»*, så søker den semantisk i <a href="../knowledge/" style="color:#0078d4;">kunnskapsbasen</a> (via Claude + OpenAI-vektorer) og svarer med relevante artikler, med direkte lenker for å åpne dem.',
            'ask_context' => '<strong>Kjenner sammenhengen</strong> &mdash; panelet vet hvilken sak du ser på, så du kan stille generelle spørsmål, og det finner ut av den relevante sammenhengen.',
            'ask_linked' => '<strong>Koblede artikler</strong> &mdash; forslagene kan klikkes og åpner den aktuelle kunnskapsartikkelen i en ny fane.',
            'ask_shared' => '<strong>Delt med kunnskapsmodulen</strong> &mdash; KI-en bruker samme nøkkel og modell som KI-søket i Kunnskap, så setter du det opp én gang, får du begge deler. Se hjelpen til kunnskapsmodulen for oppsettdetaljer.',
        ],
        'csat' => [
            'heading' => 'Kundetilfredshetsundersøkelser (KTI)',
            'intro' => 'Send innmelderen en tilfredshetsundersøkelse fra 1 til 5 på e-post når en sak er løst, ta imot svaret på en landingsside uten innlogging, og følg trender per analytiker på en egen analysesid.',
            'modes_heading' => '<strong>To utløsermåter &mdash; velg én</strong>',
            'mode_auto' => '<strong>Automatisk ved lukking</strong> &mdash; undersøkelsen legges i kø automatisk når en sak går over i en lukket status. Analytikeren trenger ikke å gjøre noe &mdash; løsningen driver undersøkelsen.',
            'mode_manual' => '<strong>Bare manuelt</strong> &mdash; analytikeren klikker ⭐ <strong>Tilbakemelding</strong>-knappen i verktøylinjen på saken når de vil spørre. Nyttig når du heller vil avgjøre sak for sak om du skal be om tilbakemelding.',
            'starters_note' => '<strong>Saker opprettet av en Nyansatte og avgang-sak</strong> (et malsteg som opprettes som sak) får ingen automatisk undersøkelse, og bestilleren deres ingen automatiske e-poster, med mindre malen krysser av for <strong>Send e-post til bestilleren om disse sakene</strong>. Hver e-post som ikke sendes, er oppført i postkassens sendelogg som hoppet over, med årsaken. Saken viser hvilken sak den hører til i lenkene sine.',
            'switch_note' => 'Bruker du ikke KTI i det hele tatt? Slå den av under <strong>System &rarr; Moduler &rarr; Tilgjengelighet &rarr; Sakfunksjoner</strong>, så forsvinner den: ingen undersøkelser, ingen KTI-side, ingen Be om tilbakemelding-knapp, og gamle undersøkelseslenker sier at tilbakemeldinger ikke lenger samles inn. Ingenting slettes.',
            'mode_off' => '<strong>Av</strong> &mdash; funksjonen er slått av; det sendes ingen e-poster med undersøkelser.',
            'modes_choose' => 'Velg under <strong>Saker &rarr; Innstillinger &rarr; KTI</strong>. Den manuelle knappen virker fortsatt i <em>automatisk</em> modus &mdash; analytikere kan be om tilbakemelding på nytt på en sak som allerede er undersøkt, om det trengs.',
            'template_heading' => '<strong>E-postmalen</strong>',
            'template_body' => 'Innholdet i e-posten med undersøkelsen kommer fra den eksisterende fanen <strong>E-postmaler</strong> &mdash; opprett en mal med hendelsen <strong>KTI-undersøkelse</strong> (den nye hendelsen ved siden av <em>Sak tildelt</em> / <em>Sak lukket</em>) og legg flettekoden <code>[csat_link]</code> der du vil at vurderingslenken skal stå. Vanlige flettekoder (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) er tilgjengelige som normalt.',
            'template_tip' => 'Finnes det ingen aktiv KTI-mal, nekter <em>Tilbakemelding</em>-knappen med en tydelig feilmelding, og den automatiske utløseren hopper stille over &mdash; du kan aldri produsere døde undersøkelseslenker.',
            'survey_heading' => '<strong>Undersøkelsessiden</strong>',
            'survey_body' => 'Innmelderen klikker lenken i e-posten og lander på en side uten innlogging med en velger fra 1 til 5 pluss et valgfritt kommentarfelt. To visuelle stiler kan velges under <strong>Innstillinger &rarr; KTI</strong>:',
            'survey_stars' => '<strong>Stjerner</strong> &mdash; klassisk oppførsel der de fylles etter hvert som du holder over. Holder du over stjerne 3, fylles 1, 2 og 3 i gull. Klikk for å låse.',
            'survey_emojis' => '<strong>Emojier</strong> &mdash; 5 ansikter 😡 🙁 😐 🙂 😀 starter i gråtoner med 40 % dekkevne; den du holder over eller velger, får full farge igjen i 1,25 &times; størrelse. Klikk for å låse.',
            'survey_store' => 'Begge måtene lagrer det samme tallet fra 1 til 5, så oversikter og gjennomsnitt virker likt uansett hvilken stil som er i bruk. Undersøkelseslenken virker bare én gang &mdash; når brukeren har sendt inn, avviser den samme lenken et nytt svar.',
            'chat_heading' => '<strong>Spørre chatkunder i chatten deres</strong>',
            'chat_body' => 'Når <strong>Spør chatkunder i chatten deres</strong> er avkrysset, blir en kunde som tok kontakt på WhatsApp, Telegram, Slack, Microsoft Teams eller Mattermost spurt i den chatten i stedet for på e-post &mdash; fem knapper på Telegram, Teams og Mattermost, &ldquo;svar med ett enkelt siffer&rdquo; andre steder. Svaret havner i de samme resultatene som en undersøkelse sendt på e-post.',
            'chat_rules' => 'WhatsApp får bare spørsmålet mens svarvinduet på 24 timer er åpent; utenfor det, eller hvis chatmeldingen ikke kan sendes, brukes e-postundersøkelsen i stedet. Et siffer teller som vurdering bare rett etter spørsmålet &mdash; i samme chat, innen en uke og før kunden har skrevet noe annet &mdash; så &ldquo;3&rdquo; som svar på et spørsmål fra en analytiker forblir en melding. Av etter oppgradering; på for en ny installasjon.',
            'analytics_heading' => '<strong>Analysesiden</strong>',
            'analytics_body' => 'Klikk ⭐ <strong>KTI</strong>-knappen i navigasjonen (mellom Vaktliste og Innstillinger) for å åpne analyseoversikten på <code>tickets/csat/</code>. Tidsrommet kan velges: 7 / 30 / 90 / 365 dager.',
            'card_kpi_title' => 'Nøkkeltall',
            'card_kpi_body' => 'Gjennomsnittlig vurdering (av 5), antall svar, svarandel (svart ÷ sendt)',
            'card_dist_title' => 'Fordeling av poeng',
            'card_dist_body' => 'Stolpediagram over vurderingene 1–5 med nøyaktige antall og prosenter',
            'card_leader_title' => 'Rangering per analytiker',
            'card_leader_body' => 'Gjennomsnittlig vurdering + antall svar per analytiker, sortert på snitt synkende. Bruk den til utviklingssamtaler',
            'card_recent_title' => 'Nylige svar',
            'card_recent_body' => 'Vurderingene med de nyeste først, 25 per side, med kommentarene deres i fritekst og kunden som la dem igjen, koblet tilbake til kildesaken',
            'analytics_filters' => 'Begrens siden med filtrene under overskriften: et datointervall <strong>Fra / Til</strong> (i stedet for dagknappene), et <strong>Vurdering</strong>sbånd (Positive 4-5, Nøytrale 3, Negative 1-2), en <strong>Analytiker</strong> og en <strong>Kunde</strong>. Analytiker og kunde begrenser hvert tall på siden; vurderingsbåndet begrenser bare listen over svar, så gjennomsnittet fortsatt betyr noe. På en mobil ligger filtrene bak knappen <strong>Filtre</strong> nederst på skjermen. En filtrert side kan bokmerkes.',
            'analytics_company' => 'Hvert tall følger <strong>firmavelgeren</strong> i toppteksten: firmaet du har valgt, eller alle firmaer du kan se under <strong>Alle selskaper</strong>.',
            'analytics_tip' => 'Tilskrivingen per analytiker overlever at saken tildeles på nytt, fordi analytiker-ID-en fanges opp på undersøkelsesraden idet den sendes, og ikke slås opp i etterkant. Går en sak fra hånd til hånd før den lukkes, er det analytikeren som faktisk lukket den, som eier vurderingen.',
            'one_heading' => '<strong>Én undersøkelse per sak</strong>',
            'one_body' => 'Er <em>Én undersøkelse per sak</em> slått på (standard), får en sak som gjenåpnes og lukkes igjen, bare en ny undersøkelse når en analytiker utløser den manuelt &mdash; det hindrer at en ustabil sak som stadig går i sirkel, spammer med undersøkelser. Slå det av hvis du vil at hver lukking skal utløse en ny undersøkelse.',
        ],
        'users' => [
            'heading' => 'Brukerhåndtering',
            'intro' => '<strong>Brukere</strong>-knappen i navigasjonen åpner <code>tickets/users.php</code> &mdash; en katalog over alle sluttbrukere (de som melder inn saker, ikke analytikere), sammen med sakshistorikken til hver av dem.',
            'p_intro' => 'Brukere havner i systemet på fire måter som skjer av seg selv &mdash; selvregistrering i portalen, en innkommende e-post fra en ny avsender, postkassehenteren, eller arbeidsflytmotoren som oppretter en fra en utløst sak. Det dekker de fleste tilfellene, men Brukere-siden lar deg også <strong>opprette på forhånd</strong> (for eksempel en nyansatt som snart trenger tilgang) og <strong>redigere</strong> eller <strong>slette</strong> eksisterende rader.',
            'add_heading' => '<strong>Legg til bruker</strong>',
            'add_body' => 'Knappen <strong>Legg til</strong> i toppen av brukerlisten åpner personredigeringen. Det er den samme redigeringen som <strong>Ressurser &rarr; Brukere</strong> åpner, så en person legges til og endres på samme måte uansett hvilken skjerm du er på:',
            'add_email' => '<strong>E-post</strong> &mdash; valgfritt, fordi personer som logger inn via en katalog kanskje ikke har noen postkasse; de finnes i stedet med påloggingsnavnet. Oppgi enten en e-postadresse eller et visningsnavn. En adresse må være unik og kan ikke tilhøre en analytiker.',
            'add_names' => '<strong>Visningsnavn / foretrukket navn</strong> &mdash; valgfritt. Foretrukket navn er det brukeren ser seg selv hilst med i e-poster (for eksempel <em>«Ed»</em> i stedet for <em>«Ed Mozley»</em>).',
            'add_password' => '<strong>Passord</strong> &mdash; valgfritt. Lar du det stå tomt, opprettes en konto <em>uten passord</em> &mdash; nøyaktig den samme tilstanden brukere som kommer inn via e-post, starter i. Brukeren kan senere ta over kontoen gjennom registreringsflyten i selvbetjeningsportalen ved å sette sitt eget passord.',
            'add_details' => '<strong>Stillingstittel, avdeling, kontor, telefon, mobil, ansattnummer og leder</strong> &mdash; alt er valgfritt, og alt beskriver <em>personen</em> og ikke påloggingen. Verdt å fylle ut: <strong>kontor</strong> forteller deg hvilket sted noen er på før du begynner å lete etter dem, <strong>leder</strong> registrerer rapporteringslinjen (skriv en del av et navn for å finne dem), og <strong>ansattnummer</strong> er koblingsnøkkelen når du avstemmer mot et lønnssystem som aldri har hørt om en e-postadresse. Når du importerer fra en katalog, kommer alt dette ferdig utfylt. En CardDAV-adressebok fyller ut alt unntatt ansattnummer og leder, som et kontaktkort ikke har noe sted å lagre.',
            'managed_heading' => '<strong>Personer vedlikeholdt et annet sted</strong>',
            'source_body' => '<strong>Hvor en person kommer fra</strong> er angitt i detaljene deres (<em>Detaljer fra: Contoso AD - katalog</em>), og <strong>Kilde</strong>-filteret under søkefeltet viser bare personene fra én katalog eller adressebok, eller bare de som er lagt til i FreeITSM, med et antall ved siden av hver. Det vises så snart noen er koblet til en kilde.',
            'add_book_body' => '<strong>Legg til i adressebok.</strong> Noen som har sendt e-post inn, finnes her, men i ingen adressebok. Hvis en administrator har slått på <em>La analytikere legge personer til i denne adresseboken</em> (System &rarr; Autentisering, på adresseboken), får den personen en <strong>Legg til i adressebok</strong>-knapp ved siden av Rediger. Den spør først, og viser hva som kommer på kortet, og oppretter deretter kontakten og kobler dem sammen &mdash; samme person, ikke en kopi. Den legger ikke til noen hvis e-postadressen allerede finnes i boken (kjør importen i stedet), og den sørger for at neste import fanger opp den nye kontakten, eller den tar kortet ut igjen.',
            'managed_body' => 'Der en person ble importert &mdash; fra LDAP eller Active Directory, eller fra en CardDAV-adressebok &mdash; er detaljene kilden eier <strong>skrivebeskyttet</strong>, og dialogboksen gråtoner dem. Uansett hvor de kom fra, er det sannhetskilden, og neste import ville overskrevet alt som er skrevet inn her, så lagringen avvises helt i stedet for å bli godtatt og stille tilbakestilt en time senere. <strong>Hvilke</strong> detaljer det gjelder, avhenger av kilden: en katalog eier alle sju, mens en adressebok eier fem &mdash; den har ingen plass å lagre et ansattnummer eller en rapporteringslinje, så de to forblir dine å fylle ut. Og hvis adresseboken har <em>skriv endringer tilbake</em> slått på, er ingen av dem låst: det du skriver, sendes til kontaktkortet, så det er ingenting for neste import å tilbakestille. Alt annet på posten, inkludert selskapet og passordet deres, er alltid redigerbart.',
            'edit_heading' => '<strong>Rediger bruker</strong>',
            'edit_body' => 'Velg en bruker fra listen, og klikk deretter <strong>Rediger</strong> i detaljtoppen. Samme redigering, forhåndsutfylt. Å lagre uten passord lar den eksisterende hashen stå urørt; å oppgi et passord tilbakestiller den. Hvis lederen deres er noen i et firma du ikke kan se, sier Leder-boksen fra om det, og lederen beholdes som den er med mindre du velger noen andre.',
            'signin_body' => '<strong>Logger inn med</strong> viser hvilken SSO-leverandør en person er koblet til. <strong>Fjern kobling</strong> ved siden av fjerner, etter en bekreftelse, den koblingen slik at neste innlogging starter på nytt &mdash; for noen som har byttet til en annen leverandør, eller ble koblet til feil konto. Det tilbys ikke for personer som styres av en katalogsynkronisering, som bare ville koblet dem igjen.',
            'company_body' => '<strong>Firma</strong> vises når du har mer enn ett. For en ny person finner et tomt felt firmaet ut fra e-postadressen; for en eksisterende person betyr tomt ingen firma, og sakene deres går til sortering.',
            'managers_heading' => '<strong>Ledere</strong>',
            'managers_body' => 'En person kan gjøres til <strong>leder</strong> i selvbetjeningsportalen: de får en fane <strong>Teamsaker</strong> som viser sakene til personene de leder. Den er av til en administrator slår den på under <strong>System &rarr; Ledere</strong>, som også bestemmer om ledere kan svare på eller lukke disse sakene, og hva de ser av en konfidensiell sak (ingenting, som standard).',
            'managers_sources' => 'Noen er leder på to måter, begge samtidig: de er <strong>Leder</strong> på andre personers oppføringer (for hånd, eller fra katalogen din), og de har <strong>ledelseslinjer</strong> satt opp for seg. Klikk <strong>Ledertilgang</strong> ved siden av Rediger for å åpne en fullskjermsside for den personen, der du kan gi dem alle, bestemte personer, persongrupper, avdelinger eller hele rapporteringslinjen deres, og <strong>utelate</strong> personer &mdash; en utelatelse vinner alltid, også over feltet Leder. Siden viser hvor mange personer de kan se og lister dem opp, beregnet som om ledere allerede var slått på, så du kan sjekke før du slår dem på. Klikk på hvem som helst i den listen for å se <strong>hvorfor</strong> lederen kan se dem, og hvordan du stopper det.',
            'managers_rules' => 'En leder ser bare personer i sitt eget firma, aldri seg selv, og ingenting i det hele tatt etter at vedkommende har sluttet. Avdelinger samsvarer på navnet som er skrevet inn på hver person, så en omdøpt avdeling slutter å samsvare &mdash; siden, og System &rarr; Ledere, advarer om en avdelingslinje som ikke samsvarer med noen. Som standard kan bare administratorer endre ledelseslinjer; System &rarr; Ledere kan åpne for alle som kan redigere personer.',
            'delete_heading' => '<strong>Slett bruker</strong>',
            'delete_body' => '<strong>Slett</strong>-knappen er <strong>trygg mot fremmednøkler</strong>: den nekter hvis brukeren er innmelder på noen saker eller har rader i <code>users_assets</code>, og gir en tydelig melding: <em>«Kan ikke slette: denne brukeren er innmelder på N sak(er). Tildel eller lukk de sakene først.»</em> Revisjonshistorikken kan aldri brytes i stillhet.',
            'tip' => 'Alle feltene i vinduet har nettleserens autofyll slått av (inkludert <code>autocomplete="new-password"</code> på passordfeltet), slik at analytikerens egne lagrede påloggingsopplysninger ikke foreslås inn i et skjema som har som eneste formål å opprette <em>en annens</em> kort.',
            'groups_heading' => '<strong>Grupper</strong>',
            'groups_body' => 'Fanen <strong>Grupper</strong> ved siden av <strong>Personer</strong> inneholder navngitte grupper av personer &mdash; analytikere og selvbetjeningsportalbrukere sammen i samme gruppe. En gruppe opprettes én gang her og brukes deretter i hele FreeITSM, slik at du kan gi den tilgang til en kunnskapsmappe eller tildele den et kurs uten å bygge samme liste to ganger.',
            'groups_make' => '<strong>Opprett en</strong> med <strong>Legg til</strong> på Grupper-fanen: et navn, og en beskrivelse som er verdt å fylle ut, fordi neste person må kunne forstå hva gruppen er til for.',
            'groups_add' => '<strong>Legg til personer</strong> ved å søke etter dem &mdash; det finner analytikere og portalbrukere sammen, så du trenger ikke vite hvilken type noen er.',
            'groups_expiry' => '<strong>Gi et medlemskap en sluttdato</strong> der tilgangen er midlertidig. Tre ingeniører på stedet i to uker legges inn med en siste dag og faller automatisk ut av gruppen når den passerer. Et utløpt medlemskap blir stående på listen, merket som utløpt, slik at du fortsatt kan se hvem som hadde tilgang og til når.',
            'groups_uses' => '<strong>Hva en gruppe er nyttig til:</strong> å gi tilgang til en kunnskapsmappe, og å tildele LMS-opplæring til flere personer samtidig. Endringer i medlemskap trer i kraft umiddelbart &mdash; det er ingenting å bruke på nytt etterpå.',
            'groups_admin' => '<strong>Alle med Saker-modulen kan se gruppene; bare en administrator kan endre en.</strong> Å legge noen til i en gruppe kan også gi dem tilgang til en begrenset kunnskapsmappe, så det er en tilgangstildeling, ikke bare arkivering.',
        ],
        'dash' => [
            'heading' => 'Oversikt',
            'intro' => 'Saksoversikten gir analyser med ett blikk, i tilpassbare Chart.js-elementer. Hver analytiker har sitt eget oppsett, så du kan konsentrere deg om målene som betyr noe for din rolle &mdash; enten det er din egen arbeidsmengde, teamets gjennomstrømning eller SLA-etterlevelse.',
            'step1' => '<strong>Åpne biblioteket</strong> &mdash; klikk Rediger oversikt for å gå inn i redigeringsmodus, og bla så gjennom elementbiblioteket. Velg blant ferdiglagde elementer, eller lag ditt eget ved å velge en diagramtype og egenskapen som skal summeres.',
            'step2' => '<strong>Legg til elementer</strong> &mdash; klikk +-knappen på et element i biblioteket for å legge det til på oversikten din. Det dukker opp med én gang og begynner å vise ferske data fra saksdatabasen din.',
            'step3' => '<strong>Sett det opp</strong> &mdash; klikk tannhjulet på et element for å tilpasse tittel, diagramtype (stolpe, kake, smultring, linje, stablet stolpe, flerlinje), filter på tidsrom, filter på avdeling og tidsgruppering (daglig, ukentlig, månedlig).',
            'step4' => '<strong>Ordne dem</strong> &mdash; dra og slipp elementer for å endre rekkefølgen. Oppsettet ditt lagres per analytiker, så det består fra gang til gang.',
            'examples' => 'Vanlige eksempler på elementer er: <strong>Saker etter status</strong> (smultringdiagram som viser åpne mot løste mot lukkede), <strong>Saker etter prioritet</strong> (stolpediagram over mengde per alvorlighetsgrad), <strong>Ukentlig mengde</strong> (linjediagram som følger nye saker over tid) og <strong>Arbeidsmengde per analytiker</strong> (stablet stolpe som viser de aktive sakene til hver analytiker).',
            'tip' => 'Bruk filtre på tidsrom på enkeltelementer for å sammenligne dagens resultater med tidligere perioder. En visning av typen «Denne måneden mot forrige måned» hjelper deg for eksempel å oppdage trender i saksmengden tidlig.',
        ],
        'cal_rota' => [
            'switch_note' => 'Bruker du ikke vaktlisten? Slå den av under <strong>System &rarr; Moduler &rarr; Tilgjengelighet &rarr; Sakfunksjoner</strong> - siden, innstillingene og War room-botens <em>hvem som har vakt</em> forsvinner, og ingenting slettes.',
            'heading' => 'Kalender &amp; vaktliste',
            'intro' => 'To planleggingsverktøy hjelper teamet ditt med å holde orden: en sakskalender som viser arbeidsmengden over tid, og en bemanningsplan for å håndtere skift og beredskap.',
            'cal_heading' => '<strong>Kalendervisning</strong>',
            'cal_body' => 'Kalenderen plotter hver sak som har <code>work_start_datetime</code> satt (via høyreklikkvinduet <em>Før tid</em> / <em>Planlegg</em>) som en farget blokk på det planlagte tidspunktet. Røde blokker er <em>Høy</em> prioritet, grønne er <em>Lav</em>, blå er alt annet. Bruk <em>I dag</em>, pilene <em>&lt;</em> / <em>&gt;</em> og bryteren <strong>Måned / Uke / Dag</strong> til høyre i overskriften for å navigere &mdash; <em>Forrige</em> / <em>Neste</em> flytter en måned, uke eller dag avhengig av hvilken visning som er aktiv.',
            'cal_scope' => '<strong>Mine eller Alle.</strong> Kalenderen åpnes med ditt eget planlagte arbeid, med en <strong>Alle</strong>-bryter ved siden av visningsknappene; valget ditt huskes. I Alle har hver sak en <strong>farge for den som eier den</strong>, med en tegnforklaring som navngir personene som faktisk vises på skjermen, og å peke på en sak viser hvem den tilhører uten at du trenger å se bort. Ingenting skjules for noen &mdash; dette er de samme sakene innboksen allerede viser.',
            'cal_edit' => '<strong>Omorganisere arbeid.</strong> <strong>Dra en sak</strong> til en annen dag eller et annet tidspunkt: i månedsvisning beholder den tiden sin, og i uke- og dagvisning tar den tiden du slipper den på, avrundet til nærmeste kvarter. Lengden endres aldri &mdash; å dra sier <em>start den da</em>, ikke <em>gjør den lengre</em>. Eller <strong>klikk på en sak</strong> for å åpne den, der du kan endre dato, tid, varighet og innstillingen for hele dagen, eller tømme tidsplanen helt. Kalenderen <strong>oppdaterer seg også selv hvert par sekunder</strong>, slik at noe en kollega planlegger, dukker opp uten at du laster inn på nytt &mdash; og den venter mens du har en sak åpen eller er midt i å dra noe.',
            'cal_month' => '<strong>Månedsvisning</strong> &mdash; det klassiske rutenettet med seks rader og en stripe med ukedager øverst; hver dagcelle viser opptil tre sakspiller med starttidspunktet sitt, pluss en <em>+N til</em>-lenke som tar deg til dagsvisningen for den datoen. I dag er uthevet.',
            'cal_week' => '<strong>Ukesvisning</strong> &mdash; man&ndash;søn langs toppen over en loddrett tidslinje på 24 timer. Saker vises som fargede blokker på én time ved starttidspunktet sitt. Kolonnen for i dag er uthevet; ukedagsoverskriften blir stående mens timerutenettet ruller.',
            'cal_day' => '<strong>Dagsvisning</strong> &mdash; én høy kolonne for den valgte dagen, med den samme tidslinjen på 24 timer. Saker vises som større blokker med <code>saksnummer &mdash; emne</code> og starttidspunkt; klikk en for å åpne detaljene.',
            'rota_heading' => '<strong>Bemanningsplan</strong>',
            'rota_body' => 'Vaktlistesiden lar teamledere og ledere planlegge analytikerskift gjennom uken. Definer normal arbeidstid, tildel beredskapsperioder, og merk ferie eller fravær, slik at teamet alltid vet hvem som er tilgjengelig.',
            'rota_step1' => '<strong>Se vaktlisterutenettet</strong> &mdash; vaktlisten viser analytikere langs den ene aksen og dager langs den andre, med skiftblokker som gir dekningen med ett blikk.',
            'rota_step2' => '<strong>Legg til eller rediger skift</strong> &mdash; klikk en celle for å tildele en skifttype (for eksempel Tidlig, Sen, Natt, Beredskap). Endringer lagres umiddelbart.',
            'rota_step3' => '<strong>Planlegg framover</strong> &mdash; bla framover uke for uke for å bygge vaktlisten i forkant. Slik sikrer du nok dekning i kjente travle perioder, ferier eller opplæringsdager.',
            'rota_step4' => '<strong>Fyll flere celler samtidig</strong> &mdash; <strong>høyreklikk</strong> på en celle og velg <em>Kopier</em> for å hente skiftet i den, høyreklikk deretter på en annen og <em>Lim inn</em>. For mer enn én celle, <strong>dra over en blokk</strong> med dem (eller ctrl-klikk celler én etter én) og lim inn i alle sammen. Å peke på en <strong>dagsoverskrift</strong> lyser opp hele den dagen, og å peke på en <strong>analytikers navn</strong> lyser opp hele uken deres &mdash; høyreklikk på begge og lim inn i alt sammen. Der noen av cellene allerede har et skift, tilbyr menyen begge alternativene i klartekst &mdash; <em>Lim inn i alle 7</em> og <em>Lim inn i 6 tomme celler</em> &mdash; slik at du velger før du bestemmer deg, ikke etterpå. Overskriving ber deg bekrefte og sier hvor mange skift den erstatter; å fylle hullene skjer bare, siden ingenting går tapt. De samme menyene vil også <strong>tømme</strong> en dag, en uke eller et utvalg, igjen etter å ha fortalt deg hvor mange skift det fjerner.',
            'rota_step5' => '<strong>Kopier en hel dag eller en hel uke for én person</strong> &mdash; høyreklikk på en <strong>dagsoverskrift</strong> og velg <em>Kopier</em> for å hente alle skift den dagen, eller en <strong>analytikers navn</strong> for å hente hele uken deres. Å lime inn på en annen dag, eller en annen analytiker, gjør at den stemmer overens: skift kopien ikke hadde, blir tømt, slik at du får dagen du kopierte i stedet for en blanding av de to. En dag kan bare limes inn på en annen dag, og en analytiker bare på en annen analytiker &mdash; en dag er ett skift <em>per person</em>, og en uke er ett skift <em>per dag</em>, så det finnes ingen fornuftig måte å legge den ene over den andre på. Prøv det, og menyen sier fra, og sier hvor den kan gå i stedet.',
            'rota_step6' => '<strong>Kopier en hel uke</strong> &mdash; <strong>Kopier uke</strong> og <strong>Lim inn uke</strong> øverst til høyre henter alle skift i uken du ser på, og slipper dem på en annen, som er den raskeste måten å bygge en gjentakende vaktliste på. Å lime inn <em>erstatter</em> målukens innhold, så bekreftelsen forteller deg hvor mange oppføringer som er i ferd med å bli fjernet. Den berører bare dagene og personene rutenettet faktisk viser deg.',
            'tip' => 'Kombiner kalenderen og vaktlisten for effektiv kapasitetsplanlegging. Viser kalenderen en topp i saker hver mandag morgen, sørger du for at vaktlisten har ekstra dekning satt opp akkurat der.',
        ],
        'settings' => [
            'heading' => 'Innstillinger',
            'intro' => 'Innstillinger-siden er der du setter opp byggeklossene i saksbehandlingssystemet ditt. Alle oppslagsverdier, SLA-mål, e-postintegrasjon og egendefinerte felt håndteres her.',
            'sla_callout_title' => 'SLA-håndtering &mdash; hele veiledningen',
            'sla_callout_body' => 'Valgmuligheter, arbeidskalendere, statuser som setter klokken på pause, varsler ved brudd, oppsett av cron-jobb, pluss gjennomgåtte eksempler for team i én tidssone og på tvers av tidssoner. Omfattende nok til å fortjene sin egen side.',
            'card_dept_title' => 'Avdelinger',
            'card_dept_body' => 'Opprett avdelinger som IT, HR og økonomi. Hver avdeling blir en mappe i innboksen og et filter på oversikten',
            'card_types_title' => 'Sakstyper',
            'card_types_body' => 'Definer typene henvendelser servicedesken din håndterer: hendelse, tjenesteforespørsel, problem, endring. Typer hjelper analytikere med å klassifisere arbeid',
            'card_type_rules_title' => 'Type for nye saker',
            'card_type_rules_body' => 'Under Sakstyper gir du hver ny sak en type når ingen velger en: en standard, og regler foran den - etter hvordan den kom inn (e-post, portal, nettchat, telefon, overvåking ...), postkasse, opprinnelse, avdeling, ord i emnet eller bestillerens domene. Den første regelen som passer, vinner; Prøv det viser hvilken type en sak ville fått',
            'card_priorities_title' => 'Prioriteter',
            'card_priorities_body' => 'Sett prioritetsnivåer med navn, farger og sorteringsrekkefølge. Hver prioritet knyttes til et SLA-mål for respons og løsning',
            'card_statuses_title' => 'Statuser',
            'card_statuses_body' => 'Tilpass trinnene i saksforløpet. Standardstatusene er blant andre Ny, Åpen, Under arbeid, Venter, Løst og Lukket',
            'card_categories_title' => 'Kategorier',
            'card_categories_body' => 'Grupper saker etter teknisk område: maskinvare, programvare, nettverk, tilgang. Kategorier driver oppdelingen i rapporter',
            'card_sla_title' => 'SLA-mål',
            'card_sla_body' => 'Definer mål for responstid og løsningstid per prioritet. SLA-klokker vises på saker og utløser advarsler om brudd',
            'card_email_title' => 'E-postimport',
            'card_email_body' => 'Koble til en postkasse (Exchange, Microsoft 365) for å importere e-poster som nye saker automatisk. Svar trådes tilbake inn i eksisterende saker',
            'card_custom_title' => 'Egendefinerte felt',
            'card_custom_body' => 'Legg egne felt på saker for data organisasjonen din må fange opp, og som standardfeltene ikke dekker',
            'card_templates_title' => 'E-postmaler',
            'card_templates_body' => 'Sett opp varselmalene som sendes til sluttbrukere når saker opprettes, oppdateres eller løses, og for KTI-undersøkelsen. Legg inn flettekoder som [requester_name] og [csat_link]',
            'card_checklists_title' => 'Sjekklister',
            'card_checklists_body' => 'Bestem hva som skjer når noen lukker en sak som fremdeles har utestående obligatoriske sjekklistetrinn: <strong>advar</strong> og registrer et internt notat som navngir trinnene og hvem som lukket den, eller <strong>blokker</strong> lukkingen til de er utført. Håndheves overalt en sak kan lukkes - massehandlinger, REST-API-et og arbeidsflytautomatisering inkludert',
            'card_custom_fields_title' => 'Egendefinerte felter',
            'card_custom_fields_body' => 'Lag de ekstra opplysningene en type sak trenger - tekst, et tall, en dato, ja / nei, en nedtrekksliste med dine egne valg, en nett- eller e-postadresse - og knytt hvert felt til noen sakstyper eller til alle. Hvert felt velger om det må fylles ut <strong>når saken registreres</strong> (skjemaet Ny sak, REST API-et og, om ønsket, portalen), <strong>før den lukkes</strong> (etter regelen for obligatoriske felter), eller begge deler, og om <strong>bestilleren blir spurt</strong> om det i portalen - der en sakstypevelger vises så snart den endrer hva som spørres om. Svarene vises i sakens egenskapspanel og i historikken. Hvis du endrer typen på en sak, skjules svarene den nye typen ikke har, og de slettes aldri',
            'card_mandatory_title' => 'Obligatoriske felt',
            'card_mandatory_body' => 'Kryss av for feltene som må fylles ut før en sak kan lukkes - kategori, løsningskode, eier og så videre. Velg deretter hva som skjer når noen lukker en med et tomt felt: <strong>advar</strong>, <strong>advar og send e-post</strong> til for eksempel en tjenesteleveranseansvarlig, eller <strong>nekt</strong> lukkingen. En egen bryter registrerer det på saken som et internt notat. Et felt som er slått av for et selskap, er aldri påkrevd, og sammenslåing av saker utløser det aldri. Håndheves overalt en sak kan lukkes - inkludert massehandlinger, REST API-et og arbeidsflytautomatisering',
            'card_cleanup_title' => 'KI for opprydding i svar',
            'card_cleanup_body' => 'Anthropic-nøkkel + modell + tone for ✨ Rydd opp-knappen i svareditoren. Egen nøkkel atskilt fra de andre KI-funksjonene, for finmasket fakturering',
            'card_csat_title' => 'KTI',
            'card_csat_body' => 'Sendemåte (av / automatisk / manuelt), forsinkelse, vakt for én per sak, skala (stjerner eller emojier). Se del 6 for hele flyten',
            'email_heading' => '<strong>E-postimport i detalj</strong>',
            'email_body' => 'E-postimporten kobler seg til den delte postkassen din og henter inn nye meldinger som saker. Når en sluttbruker sender en e-post til supportadressen din (for eksempel support@dittfirma.no), oppretter FreeITSM en sak med emnet på e-posten som tittel og teksten som beskrivelse. Svarer avsenderen på en varsel-e-post, trådes svaret inn i den eksisterende saken i stedet for å lage et duplikat.',
            'email_step1' => '<strong>Sett opp postkassen</strong> &mdash; gå til Innstillinger og fyll inn Exchange- eller Microsoft 365-opplysningene dine. OAuth-autentisering støttes for sikre tilkoblinger uten passord.',
            'email_step2' => '<strong>Sett hentefrekvens</strong> &mdash; velg hvor ofte FreeITSM skal sjekke postkassen for nye meldinger. Kortere intervall betyr at saker opprettes raskere.',
            'email_step3' => '<strong>Sett standardverdier</strong> &mdash; velg standard avdeling, type og prioritet for saker som opprettes fra e-post. Analytikere kan justere disse etter importen.',
            'email_thread_note' => '<strong>Et svar uten saksnummer</strong> &mdash; hver e-post FreeITSM sender, har saksnummeret med, så et svar på den finner alltid saken sin. Når noen i stedet svarer på sin <em>egen</em> første e-post (for eksempel for å legge ved et vedlegg de glemte), er det ikke noe nummer å finne, og som standard starter det svaret en ny sak. Sett Saker &rarr; Innstillinger &rarr; Generelt &rarr; <strong>Et svar uten saksnummer</strong> til <strong>Kobles til saken samtalen hører til</strong>, så havner det på saken den første e-posten åpnet i stedet, og gjenåpner den hvis den var lukket (når gjenåpning er på). Bare e-poster i samme postkasse sammenlignes.',
            'email_reply_to_note' => '<strong>Hvem Svar går til</strong> &mdash; som standard er Svar-boksen adressert til personen på meldingen du leser. Hvis kolleger til bestilleren blir med i tråden og du heller vil svare bestilleren hele tiden, setter du Saker &rarr; Innstillinger &rarr; Generelt &rarr; <strong>Svar går til</strong> til <strong>Sakens bestiller</strong>. Du kan alltid endre adressen før du sender.',
            'email_sent_copy_note' => '<strong>En kopi av sendt e-post i Sendt-mappen (Basic IMAP)</strong> - en Basic IMAP-postkasse sender via SMTP, som ikke beholder noen kopi, så alle som leser den samme postkassen i Thunderbird eller nettpost ville ikke sett hva servicedesken sendte. Rediger postkassen og slå på <strong>Lagre en kopi av sendt e-post</strong>, rett under <em>Bruk IMAP-påloggingen til sending</em>: hvert svar, malbasert e-post, arbeidsflyt-e-post og system-e-post den sender, legges da også i Sendt-mappen, markert som lest. Interne varsler til analytikere arkiveres aldri. La <strong>Sendt-mappe</strong> stå tom for å bruke mappen e-postserveren din markerer som Sendt, eller skriv navnet på den. La bryteren stå av hvis e-postserveren din allerede arkiverer sendt e-post (Gmail og Microsoft 365 gjør det, og noen nettvertsselskaper) - ellers får du to kopier. <strong>Test</strong> sier hvilken mappe kopien havnet i. Hvis en kopi ikke kan lagres, er e-posten likevel sendt, og årsaken står oppført i postkassens <strong>Aktivitet</strong> &rarr; <strong>Utgående</strong>-fane som <em>Kopi til Sendt-mappen</em>.',
            'tip' => 'Bruk e-postmaler for å holde en profesjonell og enhetlig tone i all kommunikasjon med sluttbrukere. Maler støtter dynamiske plassholdere for saksreferanse, navn på innmelder, navn på analytiker og status.',
            'closemsg_heading' => '<strong>En engangsmelding når du lukker en sak</strong>',
            'closemsg_body' => 'Sett inn <code>[ticket_closed_message]</code> hvor som helst i en aktiv <strong>Sak lukket</strong>-mal, og fra da av vil det å sette en sak til en lukket status be analytikeren om en setning - <em>&ldquo;reserveladeren ligger på pulten din&rdquo;</em>, <em>&ldquo;lukkes som avtalt på telefon&rdquo;</em>. Uansett hva de skriver, havner det nøyaktig der du satte plassholderen, slik at du beholder kontrollen over ordlyden rundt den. Det er ingen innstilling, og ingenting lagrer det: ett notat, én sak, én e-post. Skriv ingenting, og linjen er rett og slett ikke der - ingen luke, ingen løs tegnsetting.',
            'closemsg_note' => '<strong>Spørsmålet vises bare når plassholderen faktisk er i malen.</strong> Uten den ville alt en analytiker skrev, blitt stille kastet bort, og hver eneste helpdesk som ikke ønsker dette, ville fått et ekstra klikk på hver eneste lukking. Så den slår seg selv på når du konfigurerer den, og holder seg unna når du ikke har gjort det.',
            'cat_heading' => '<strong>Kategorier, og de to feltene ved siden av dem</strong>',
            'cat_body' => 'En sak-<em>type</em> sier hva slags ting dette er; en <em>kategori</em> sier hva det handler om. Bygg listen under <strong>Innstillinger &rarr; Kategorier</strong>, sammen med bryterne som avgjør om noe av det i det hele tatt vises på en sak.',
            'cat_card_one_title' => 'Kategori',
            'cat_card_one_body' => 'Hva saken ble meldt som, valgt når den opprettes. En sak har nøyaktig én, så en rapport over kategoriene dine går alltid opp i antallet saker du faktisk hadde.',
            'cat_card_close_title' => 'Kategori ved lukking',
            'cat_card_close_body' => 'Den samme listen spurt om igjen når saken avsluttes. Vanligvis bekrefter analytikeren den bare &mdash; den forsvarer sin plass på de sakene der det første gjettet var feil, som er hvordan du finner ut at tolv av de trettisju "skriverproblemene" dine egentlig var nettverket.',
            'cat_card_res_title' => 'Løsningskode',
            'cat_card_res_body' => 'Hvordan saken endte, snarere enn hva den handlet om &mdash; "Løst eksternt", "Opplæring gitt", "Ingen feil funnet". Ti fornuftige er der fra starten, og du kan endre dem alle.',
            'cat_rule_off' => '<strong>Alle tre er slått av fra starten.</strong> Bygg listen din først, og slå deretter på de du vil ha. Hver kan stilles inn forskjellig for hvert selskap.',
            'cat_rule_levels' => 'Kategorier kan ha underkategorier opptil tre nivåer dypt, og ingen nivåer er obligatoriske.',
            'cat_rule_type' => 'En kategori kan knyttes til én sakstype, slik at "Brukeronboarding" bare tilbys på en tjenesteforespørsel. Koblingen tilhører toppnivåkategorien, og underkategoriene følger den.',
            'cat_rule_typechange' => '<strong>Å endre en saks type fjerner en kategori som tilhørte den gamle typen</strong>, og sier fra om det på skjermen. En kategori som ikke er knyttet til noen type, overlever endringen.',
            'cat_rule_portal' => 'Kryss av for <em>Kunder kan velge denne</em> for å tilby en kategori i selvbetjeningsportalen. Bestillere ser en kort liste i klartekst, mens analytikere ser hele treet.',
            'cat_rule_retire' => 'Slå av en kategori for å pensjonere den &mdash; den blir stående på sakene som allerede har den, og slutter å bli tilbudt på nye. Det er nesten alltid bedre enn å slette, noe som avvises så lenge noe fortsatt bruker den.',
            'cat_rule_report' => 'Alle tre kan vises som diagram på saksoversikten. De to kategoridiagrammene rulles opp til toppnivået, og saker uten noe satt telles som <em>Ikke kategorisert</em> i stedet for å skjules.',
            'cat_rule_workflow' => '<strong>Kategorier i arbeidsflyter:</strong> en arbeidsflyt kan rute saker etter kategori - en <em>Kategori</em>-betingelse virker på alle sakutløsere, og utløseren <em>En sakskategori endres</em> fanger opp en sak som er kategorisert ved sortering. Som standard samsvarer en betingelse som nevner en kategori også med underkategoriene, så «Maskinvare» fanger «Maskinvare &rarr; Bærbar»; velg <strong>Den samsvarer bare med den kategorien</strong> under <strong>Saker &rarr; Innstillinger &rarr; Kategorier &rarr; Kategorier i arbeidsflyter</strong> for at hver arbeidsflyt må nevne hver underkategori den vil ha. Når endring av en sakstype tømmer kategorien, utløses utløseren også.',
            'cat_tip' => 'Hvis du er usikker på hvor du skal begynne, la kategoriene stå tomme og slå på <strong>Løsningskode</strong> alene. Det er feltet som raskest endrer hva du gjør &mdash; at en femtedel av sakene dine kommer tilbake som "Opplæring gitt", er et dokumentasjonsproblem, ikke et IT-problem.',
        ],
        'tips' => [
            'heading' => 'Raske tips',
            'search_title' => 'Søk i alt',
            'search_body' => 'Søkevinduet ser på saksreferanser, emner, navn på innmeldere og e-postadresser. Bruk det til å finne beslektede saker raskt når en bruker ringer om noe som allerede er meldt.',
            'sla_title' => 'Følg med på SLA-ene',
            'sla_body' => 'SLA-klokker er synlige på hver sak i lesefeltet. Fargekodede markører blir gule når et brudd nærmer seg, og røde når målet er bommet på, så du kan prioritere deretter.',
            'reply_title' => 'Svar fra innboksen',
            'reply_body' => 'Du trenger ikke å åpne e-postprogrammet ditt for å svare en sluttbruker. Bruk Svar-knappen i lesefeltet for å sende en melding direkte. Den trådes inn i saken automatisk.',
            'reply_to_title' => 'Hvem Svar går til',
            'reply_to_body' => 'Svar er adressert til personen på meldingen du leser. Hvis du heller vil at det alltid går til sakens bestiller, endrer du <strong>Svar går til</strong> i Saker &rarr; Innstillinger &rarr; Generelt. Uansett kan du endre adressen, eller legge til personer i Kopi, før du sender.',
            'trail_title' => 'Bruk aktivitetssporet',
            'trail_body' => 'Før du jobber med en sak, bør du bla gjennom aktivitetssporet. Tidligere analytikernotater, e-poster og feltendringer gir deg hele sammenhengen, så du slipper å be brukeren gjenta seg.',
            'dash_title' => 'Oversikt for ledere',
            'dash_body' => 'Bygg en oversikt med elementer for SLA-etterlevelse, gjennomsnittlig løsningstid og saker per avdeling. Del den på teammøter for å drive kontinuerlig forbedring.',
            'rota_title' => 'Planlegg med vaktlisten',
            'rota_body' => 'Fyll ut vaktlisten minst to uker i forveien. Kombinert med kalendervisningen hjelper den deg å oppdage hull i dekningen før de blir et problem for responstidene.',
            'drag_title' => 'Dra for å triagere',
            'drag_body' => 'Dra saker fra listen inn i mapper for å oppdatere dem uten å åpne dem. Undermapper for avdeling + status oppdaterer begge deler på én gang. Fjærbelastet utvidelse gjør underliggende statuser tilgjengelige mens du drar.',
            'dbl_title' => 'Dobbeltklikk for fullskjerm',
            'dbl_body' => 'Ett klikk forhåndsviser en sak i lesefeltet; dobbeltklikk åpner den i fullskjerm for konsentrert arbeid. Klikk maksimer-ikonet ved emnet for å gå tilbake.',
            'rightclick_title' => 'Høyreklikk for raske handlinger',
            'rightclick_body' => 'Høyreklikk en sak for å endre status, prioritet eller tildelt analytiker med ett klikk, pluss koble CMDB-objekt og føre tid, alt uten å forlate saken du leser akkurat nå.',
            'ai_title' => 'La KI-en rydde opp i svaret ditt',
            'ai_body' => 'Skriv et grovt utkast (eller bare punkter) og klikk <strong>✨ Rydd opp</strong> &mdash; Claude skriver det om til en ordentlig e-post med hilsen, rettet grammatikk og avslutning. En angrelenke vises i 30 sekunder.',
            'feedback_title' => 'Be om tilbakemelding',
            'feedback_body' => 'Slå på KTI under <strong>Innstillinger &rarr; KTI</strong> for å spørre innmeldere automatisk når sakene deres lukkes. Trender per analytiker ligger på <code>tickets/csat/</code> &mdash; gull verdt til utviklingssamtaler.',
            'precreate_title' => 'Opprett sluttbrukere på forhånd',
            'precreate_body' => '<strong>Brukere</strong>-knappen i navigasjonen lar deg legge til en bruker før de trenger å melde en sak &mdash; la passordet stå tomt, så kan de ta over kontoen selv via selvbetjeningsportalen.',
        ],
        'companies' => [
            'heading' => 'Firmaer &amp; e-postruting',
            'intro' => 'Når installasjonen din betjener mer enn ett firma (for eksempel en IT-leverandør som støtter flere kunder), holdes sakene til hvert firma atskilt. Denne delen forklarer hvordan innkommende e-post finner riktig firma.',
            'switcher_body' => 'En <strong>firmaveksler</strong> dukker opp i toppfeltet. Den setter firmaet du jobber i &mdash; sakslisten, mappene og tellingene viser bare det firmaet, og hver sak du oppretter, havner der. Ansatte med tilgang til flere firmaer kan bytte mellom dem; det gjeldende vises alltid, så du kan ikke svare i feil sammenheng. Selve firmaene håndteres under <strong>System &rarr; Firmaer</strong>.',
            'switcher_remember' => 'For å starte hver pålogging i selskapet du sist valgte (eller i <strong>Alle selskaper</strong>) i stedet for standardselskapet, slår du på <strong>Start i selskapet jeg sist brukte</strong> under <strong>Preferanser</strong> (kontomenyen din).',
            'mailboxes_heading' => 'Hver postkasse er av én av to slag &mdash; det er dette som avgjør rutingen:',
            'card_pinned_title' => 'Knyttet postkasse',
            'card_pinned_body' => 'Dedikert til ett firma (for eksempel en kundes egen <code>itsupport@</code>). <strong>All</strong> posten dens havner hos det firmaet &mdash; avsenderen ignoreres &mdash; og svar går ut fra den, så kunden ser sin egen servicedesk fra ende til annen.',
            'card_shared_title' => 'Postkasse for delt mottak',
            'card_shared_body' => 'Én adresse som betjener mange firmaer (for eksempel en leverandørs ene <code>support@leverandoren.no</code>). Den kan ikke vite firmaet ut fra adressen alene, så den finner det ut fra <strong>hvem som sendte e-posten</strong>. Det anbefalte oppsettet for en leverandør med mange kunder.',
            'routing_heading' => 'Slik velger en postkasse for delt mottak firma',
            'routing_body' => 'For hver innkommende e-post prøver den disse i rekkefølge, og det første treffet vinner:',
            'flow_reply' => 'Svar på en sak',
            'flow_sender' => 'Kjent avsender',
            'flow_domain' => 'Kjent domene',
            'flow_triage' => 'Triage',
            'rule_reply' => '<strong>1. Svar på en eksisterende sak</strong> &mdash; gjenkjent på referansen sin; e-posten blir en del av den saken og beholder firmaet dens.',
            'rule_sender' => '<strong>2. En bestemt avsenderadresse</strong> knyttet til et firma (for eksempel <code>jane@gmail.com</code> &rarr; Acme) &mdash; det firmaet. Sjekkes før domenet, så det virker også for private adresser og webmail.',
            'rule_domain' => '<strong>3. Avsenderens domene</strong> knyttet til et firma (for eksempel alle <code>@acme.no</code> &rarr; Acme) &mdash; det firmaet.',
            'rule_triage' => '<strong>4. Ingen treff</strong> &mdash; e-posten går til <strong>triage</strong>-køen i stedet for å gå tapt (se nedenfor).',
            'keys_heading' => 'Domener &amp; bestemte avsendere (settes per firma under System &rarr; Firmaer)',
            'keys_body' => 'Dette er nøklene en postkasse for delt mottak matcher på. Hvert firma lister e-postdomenene det eier, og eventuelt enkeltadresser.',
            'card_domains_title' => 'E-postdomener',
            'card_domains_body' => 'Domenene et firma eier (acme.no, acme.co.uk). Enhver avsender på et registrert domene rutes til det firmaet. Et domene hører til bare ett firma.',
            'card_senders_title' => 'Bestemte avsendere',
            'card_senders_body' => 'Enkeltadresser knyttet til et firma, sjekket før domenet. Bruk det for en frilanser eller en liten kunde som sender fra en privat adresse.',
            'card_public_title' => 'Offentlige leverandører',
            'card_public_body' => 'Gmail, Outlook, Yahoo og lignende kan ikke knyttes som et domene (mange urelaterte personer deler dem) &mdash; knytt den nøyaktige adressen som en bestemt avsender i stedet.',
            'triage_heading' => 'Triage-køen &mdash; sikkerhetsnettet',
            'triage_body' => 'Når en e-post til delt mottak ikke treffer noe firma, havner den i <strong>Triage</strong> (nås fra firmavekseren, med en løpende telling) i stedet for å gå tapt. Hvert element viser avsender, domene, emne og hvilken postkasse den kom til. Legg den til et firma i ett trinn:',
            'triage_create' => 'Velg et eksisterende firma, eller opprett et nytt på stedet.',
            'triage_assign' => 'For et vanlig domene kan du eventuelt <strong>rute det domenet</strong> til firmaet; for en offentlig adresse eller webmail kan du eventuelt <strong>alltid legge den avsenderen</strong> dit.',
            'triage_sweep' => 'Begge valgene <em>feier</em>: de flytter alle andre e-poster i køen fra det domenet eller den adressen også, og ruter framtidig post automatisk &mdash; så du sorterer en gitt avsender bare én gang.',
            'triage_tip' => 'Ingenting går noen gang tapt. Post uten treff venter i triage til noen legger den et sted; en sak som ikke er lagt noe sted, vises i mellomtiden under standardfirmaet.',
            'test_heading' => 'Test rutingen din før du går i drift',
            'test_body' => 'Under <strong>System &rarr; Test av e-postruting</strong> kan du late som om en e-post kom inn &mdash; velg en postkasse, skriv en avsenderadresse &mdash; og se nøyaktig hvilket firma den nye saken ville havnet i (eller at den ville gått til triage), og hvilken regel som avgjorde det. Det opprettes ingenting; den bare leser innstillingene dine.',
            'settings_heading' => 'Innstillinger: delt som standard, tilpasset der det betyr noe',
            'settings_body' => 'Noen av disse innstillingene kan <strong>tilpasses per firma</strong>; andre forblir delte med vilje. Der en innstilling er en enkel liste med valg &mdash; som <strong>sakstyper</strong> og <strong>kilder</strong> &mdash; bytter du inn i et firmas sammenheng, og ser da de delte standardene (hver med et øyeikon for å skjule dem firmaet ikke bruker) pluss det firmaet har lagt til bare for seg selv. Du kan ikke skjule eller slette et valg mens åpne saker fortsatt bruker det, og selve de delte standardene redigeres fra MSP-en eller standardfirmaet.',
            'settings_custom_title' => 'Tilpasset per firma',
            'settings_custom_body' => 'Sakstyper &amp; kilder (nå), og kategorier, SLA-er &amp; arbeidstid (kommer) &mdash; ting som faktisk er ulike fra kunde til kunde.',
            'settings_global_title' => 'Delt på tvers av alle firmaer',
            'settings_global_body' => 'Statuser og prioriteter er like overalt, så rapportering på tvers av firmaer og SLA-er holder seg konsekvente; det samme gjelder teamene, vaktlisten og postkassene dine &mdash; din egen drift, ikke en kundes.',
            'allview_heading' => '<strong>Én tavle på tvers av alle selskaper</strong>',
            'allview_body' => 'Selskapsvelgeren i toppteksten har et <strong>Alle selskaper</strong>-alternativ. Alle saker du har lov til å se, vises i én liste, hvor hver rad bærer selskapet den tilhører &mdash; nyttig når du støtter flere enheter og vil ha ett samlet overblikk over dagen uten å miste oversikten over hva som er hva.',
            'allview_card_scope_title' => 'Det gir ingen ny tilgang',
            'allview_card_scope_body' => '"Alle" betyr alle selskapene du allerede kunne nå ett om gangen. En analytiker som støtter to av dine tre enheter, ser nøyaktig de to, og en analytiker med ett selskap ser en visning av det ene selskapet.',
            'allview_card_props_title' => 'Hver enhet forblir separat',
            'allview_card_props_body' => 'Åpne en sak, og typen, opprinnelsen, kategorien og løsningslisten er de som tilhører <em>det</em> selskapet &mdash; så en kategori som én enhet har og en annen ikke har, kan aldri brukes på feil sak.',
            'allview_card_new_title' => 'Nye saker spør hvilket selskap',
            'allview_card_new_body' => 'Det finnes ikke ett enkelt aktivt selskap å anta, og valget avgjør saksnummeret, postkassen svar kommer fra, og SLA-en som gjelder. Typelisten fylles ut når du har valgt.',
            'allview_rule_chip' => 'En sak som kom inn via e-post eller portalen uten å ha blitt rutet ennå, merkes <strong>Ikke rutet</strong> i stedet for å vises under Standard, slik at den skiller seg ut for sortering.',
            'allview_rule_reply' => 'Svar sendes fortsatt fra postkassen saken kom inn på &mdash; det følger saken, ikke visningen, så en kombinert tavle kan aldri sende fra feil adresse.',
            'allview_rule_knowledge' => '<strong>Spør AI</strong> søker i alle selskapene du kan se mens den kombinerte visningen er på, i stedet for bare ett. Artikler delt med alle selskaper er inkludert uansett.',
            'allview_rule_trash' => '<strong>Å tømme papirkurven strekker seg aldri over flere selskaper.</strong> Det gjelder alltid det ene selskapet du sist valgte, fordi "slett alt i papirkurven" på tvers av flere enheter samtidig ikke er det noen mener med det.',
            'allview_rule_other' => 'Bare sakslisten utvides. Ressurser, endringer, oppgaver og CMDB-en viser fortsatt ett selskap om gangen &mdash; bytt til det selskapet for å jobbe i dem.',
            'privacy_heading' => 'Sakene til hvert firma holdes private',
            'privacy_body' => 'Når du jobber i et firmas sammenheng, ser du bare <strong>det</strong> firmaets saker &mdash; i listen, i søket, på oversikter og på hver sak du åpner (inkludert e-poster, vedlegg, notater og historikk). En ansatt når bare en sak hvis de har fått tilgang til firmaet dens (du velger firmaene til hver analytiker under System &rarr; Analytikere, eller gir et helt team tilgang under System &rarr; Team), så det er ingen vei inn i en annen kundes data. Denne separasjonen håndheves overalt bak kulissene, ikke bare skjult fra visningen. På en installasjon med bare ett firma skjer det automatisk og usynlig &mdash; det finnes bare ett firma, så alt hører rett og slett til det.',
            'tip' => 'På en installasjon med bare ett firma vises ingenting av dette &mdash; det finnes ett firma, hver sak hører til det, og det er verken veksler eller triage. Disse funksjonene slår seg på først når firma nummer to finnes.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'SLA-håndtering',
        'back_link' => '&larr; Tilbake til saksveiledningen',
        'sidebar_title' => 'SLA-veiledning',
        'hero_title' => 'SLA-håndtering',
        'hero_sub' => 'Mål for responstid og løsningstid som tar hensyn til arbeidstid, med varsler ved brudd per avdeling',
        'nav' => [
            'overview' => 'Oversikt',
            'building_blocks' => 'Byggeklosser',
            'behaviour_settings' => 'Innstillinger for oppførsel',
            'breach_notifications' => 'Varsler ved brudd',
            'cron_setup' => 'Oppsett av cron-jobb',
            'worked_examples' => 'Gjennomgåtte eksempler',
            'troubleshooting' => 'Feilsøking',
        ],
        'overview' => [
            'heading' => 'Oversikt',
            'sub' => 'Hva SLA-er er, hvorfor de betyr noe, og hvordan FreeITSM-motoren virker på et overordnet nivå.',
            'p1' => 'En tjenestenivåavtale (SLA) er et løfte om hvor raskt teamet ditt skal svare på og løse en sak. FreeITSM følger to klokker per sak: <strong>respons</strong> (tiden fra saken opprettes til første handling fra en analytiker) og <strong>løsning</strong> (tiden fra saken opprettes til den lukkes). Begge målene settes per prioritet &mdash; så en P1 kan ha 30 minutter på respons og 4 timer på løsning, mens en P4 kan ha 8 arbeidstimer og 5 arbeidsdager.',
            'switch_note' => 'Bruker du ikke SLA-er? Slå SLA av under <strong>System &rarr; Moduler &rarr; Tilgjengelighet &rarr; Sakfunksjoner</strong>: klokker, bruddvarsler og SLA-arbeidsflytutløsere stopper, mens forretningskalenderne blir værende for nettchattens åpningstider. Når du slår den på igjen, blir du spurt om du vil sende varslene som ble gått glipp av mens den var av, eller hoppe over dem.',
            'p2' => 'SLA-motoren i FreeITSM er bygget på fire designvalg det er verdt å forstå:',
            'choice_business' => '<strong>Arbeidstid, ikke klokketid.</strong> En P2 som meldes 16.30 med et responsmål på én time, bryter ikke 17.30 hvis kontoret stenger klokken 17. Klokken går videre klokken 9 neste arbeidsdag. Dette er bransjestandarden og den eneste rettferdige modellen når analytikere går hjem om kvelden.',
            'choice_pause' => '<strong>Kan settes på pause.</strong> Når en sak har en status merket «Setter SLA på pause» (for eksempel <em>Venter på svar</em> eller <em>På vent</em>), stopper klokken. Den går videre når saken flyttes tilbake til en status det jobbes i.',
            'choice_compute' => '<strong>Regnes ut ved lesing, ikke lagret.</strong> Motoren regner ut SLA-tilstanden fra revisjonsloggen til saken hver gang du ser på den. Det finnes ingen lagrede tellere som kan komme ut av takt. Endrer du timene i en arbeidskalender senere, blir SLA-en for hver historisk sak regnet om mot de nye timene neste gang den vises.',
            'choice_cutoff' => '<strong>Grense for håndheving.</strong> En administratorstyrt «Håndhev SLA-er fra»-dato betyr at eksisterende saker i systemet ditt ikke plutselig blir brudd med tilbakevirkende kraft når du slår på SLA-er. Bare saker som er opprettet på eller etter grensen, følges.',
            'tip' => 'Er du ny i ITIL: responstid handler om bekreftelse (noen har tatt tak i den); løsningstid handler om fullføring (brukerens problem er løst). De to klokkene går uavhengig av hverandre og har ulike mål.',
        ],
        'blocks' => [
            'heading' => 'De fire byggeklossene',
            'sub' => 'Sett opp disse fire tingene, så virker SLA-oppfølgingen. Alt annet er finpuss du kan velge selv.',
            'cal_heading' => '1. Arbeidskalendere',
            'cal_intro' => 'En kalender definerer når servicedesken din er åpen. Hver kalender har:',
            'cal_tz' => '<strong>Tidssone</strong> &mdash; en IANA-tidssone (for eksempel <code>Europe/Oslo</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Overgangen til og fra sommertid håndteres automatisk.',
            'cal_hours' => '<strong>Arbeidstid per uke</strong> &mdash; én rad per ukedag med en avkrysningsboks for åpent og start- og sluttidspunkt. Nye kalendere står som standard på man–fre 09.00–17.00, stengt lør/søn. En rad som ikke er merket som åpen, betyr at servicedesken er stengt den dagen.',
            'cal_holidays' => '<strong>Helligdager</strong> &mdash; dato + valgfritt navn. Helligdager overstyrer ukemønsteret (servicedesken er stengt selv om det faller på en mandag).',
            'cal_default' => '<strong>Standardmerket</strong> &mdash; nøyaktig én kalender er standard. Nye prioriteter arver den med mindre du sier noe annet.',
            'cal_outro' => 'Du kan opprette så mange kalendere du trenger &mdash; én per kontor, én per team, én for VIP-kunder med utvidet åpningstid. De deles av SLA-målene og motoren som sjekker brudd.',
            'prio_heading' => '2. Prioriteter med SLA-mål',
            'prio_intro' => 'Under Prioriteter-fanen (eller via tabellen SLA-mål på SLA-fanen) kan hver prioritet ha:',
            'prio_response' => '<strong>Responsmål (minutter)</strong> &mdash; hvor lenge det går til første handling fra en analytiker.',
            'prio_resolution' => '<strong>Løsningsmål (minutter)</strong> &mdash; hvor lenge det går til saken er lukket.',
            'prio_calendar' => '<strong>Kalender</strong> &mdash; hvilken arbeidskalender klokken til denne prioriteten går mot. La feltet stå tomt for å bruke standardkalenderen.',
            'prio_outro' => 'Lar du begge målfeltene stå tomme, slås SLA-oppfølgingen av helt for den prioriteten &mdash; nyttig for en prioritet som «Til informasjon» eller «Etterslep», der det ikke er noe tidspress.',
            'pause_heading' => '3. Statuser som setter SLA på pause',
            'pause_intro' => 'Under Statuser-fanen finnes en egen kolonne, «Setter SLA på pause». Merk enhver status som betyr at saken er blokkert av noe utenfor teamets kontroll. Vanlige kandidater er:',
            'pause_awaiting' => '<strong>Venter på svar</strong> &mdash; kunden skylder oss informasjon. Nesten universelt godtatt som en rimelig pause.',
            'pause_vendor' => '<strong>På vent (leverandør)</strong> &mdash; venter på Microsoft eller annen tredjepartsstøtte.',
            'pause_change' => '<strong>På vent (endringsvindu)</strong> &mdash; planlagt til et framtidig vedlikeholdsvindu.',
            'pause_parts' => '<strong>På vent (deler)</strong> &mdash; venter på levering av maskinvare.',
            'pause_warn' => 'En generell «På vent»-status kan misbrukes som en nødutgang fra SLA-en når en sak er vanskelig eller analytikeren har mye å gjøre. Har teamet ditt disiplin, går det fint. Har det ikke det, bør du vurdere å erstatte den med de mer spesifikke variantene ovenfor, eller stole på <strong>Watchtower</strong>-oversikten, som markerer saker som har stått på pause i over 24 timer, med et gult varsel.',
            'cutoff_heading' => '4. Grense for håndheving (<code>Håndhev SLA-er fra</code>)',
            'cutoff_p1' => 'Den aller viktigste globale innstillingen. Helt til du setter et tidspunkt her, er SLA-oppfølgingen slått av: ingen klokker går, ingen merker vises i innboksen, ingen e-poster om brudd sendes. Setter du den til et tidspunkt tilbake i tid, slås SLA-er på med tilbakevirkende kraft fra det punktet. Setter du den fram i tid, planlegger du når de skal slås på.',
            'cutoff_p2' => 'De fleste team setter denne til «nå» når de slår på SLA-er for første gang &mdash; eksisterende saker beholder tilstanden de hadde før SLA-en, og nye saker fra det øyeblikket følges.',
            'company_heading' => 'Hver kunde sine egne prioriteter og tider',
            'company_p1' => 'På en installasjon som betjener flere selskaper kan en prioritet eller en forretningskalender være <strong>delt</strong> av alle selskaper eller tilhøre <strong>ett selskap</strong> - velg i <strong>Selskap</strong>-feltet når du legger den til. Et selskap ser sine egne prioriteter pluss de delte det ikke har skjult, og starter nye saker på sin egen standard (ellers den delte standarden). Hver prioritetsvelger følger sakens selskap, og hver kanal som åpner en sak, starter den på det selskapets standard.',
            'company_p2' => 'Klokken går etter prioritetens egen kalender; har den ingen, etter selskapets standardkalender; deretter den delte standarden. En delt prioritet kan bare bruke delte kalendere. Å flytte en sak til et selskap som ikke kan bruke prioriteten, bytter den til det selskapets standard, i sakens historikk.',
            'company_note' => 'Å endre en <strong>delt</strong> prioritet eller kalender endrer den for alle selskaper, så det krever tilgang til alle selskaper. Et selskaps egne krever tilgang til det selskapet. På en installasjon med ett selskap er alt dette usynlig - alt er delt.',
        ],
        'behaviour' => [
            'heading' => 'Innstillinger for oppførsel',
            'sub' => 'Disse styrer hvordan motoren reagerer i grensetilfeller. Standardverdiene er fornuftige &mdash; du trenger bare å se på dem igjen hvis du har en bestemt preferanse.',
            'prio_heading' => 'Når prioriteten endres underveis',
            'prio_intro' => 'Hvis en P3-sak oppgraderes til P1 halvveis (fordi problemet viser seg å være større enn antatt), finnes det tre rimelige oppførsler:',
            'prio_forward' => '<strong>Framover (standard)</strong> &mdash; behold de opptjente arbeidsminuttene og bare bytt mål. Hadde saken brukt 2 timer av P3-målet på 8 timer, har den nå brukt 2 timer mot P1-målet på 1 time &mdash; altså er den allerede i brudd. Det kan forsvares: saken VAR en P1 hele tiden, teamet skjønte det bare ikke.',
            'prio_recompute' => '<strong>Regn om</strong> &mdash; nullstill klokken og bruk det nye målet med tilbakevirkende kraft fra saken ble opprettet. En ren omregning.',
            'prio_reset' => '<strong>Nullstill</strong> &mdash; start den nye klokken på nytt fra det øyeblikket prioriteten ble endret. Mest tilgivende overfor teamet, men kunder kan føle seg lurt hvis en sak med høy prioritet plutselig får en fersk og lang klokke.',
            'reopen_heading' => 'Når en lukket sak gjenåpnes',
            'reopen_intro' => 'Hvis en sak gjenåpnes (brukeren svarer etter at den er lukket):',
            'reopen_reset' => '<strong>Nullstill (standard)</strong> &mdash; start en fersk klokke for både respons og løsning fra gjenåpningen. Behandle gjenåpningen som en ny sak i praksis.',
            'reopen_continue' => '<strong>Fortsett</strong> &mdash; gå videre fra tiden som var gått ved lukking. De opprinnelige SLA-målene fortsetter å gjelde.',
            'first_heading' => 'Definisjonen av første respons',
            'first_intro' => 'Hva teller som «første respons» &mdash; øyeblikket som stopper responsklokken?',
            'first_either' => '<strong>Begge deler (standard)</strong> &mdash; den første handlingen fra en analytiker av et hvilket som helst slag: en utgående e-post, en statusendring, en tildeling.',
            'first_status' => '<strong>Statusendring</strong> &mdash; bare en statusendring bort fra standardstatusen teller. Strengere &mdash; analytikeren må faktisk ha jobbet med saken, ikke bare klikket på den.',
            'first_email' => '<strong>Utgående e-post</strong> &mdash; bare et e-postsvar til innmelderen teller. Strengest &mdash; kunden må ha hørt fra oss.',
            'warn_heading' => 'Prosent for advarselsterskel',
            'warn_body' => 'Hvor langt ut i SLA-målet markøren skal gå fra grønn til gul. Standarden er 80 % &mdash; så et responsmål på 60 minutter blir gult etter 48 minutter. Den driver også varslene med utløseren advarsel.',
        ],
        'breach' => [
            'heading' => 'Varsler ved brudd',
            'sub' => 'E-postregler som kan settes opp per avdeling, og som utløses når SLA-er nærmer seg brudd (advarsel) eller faktisk bryter.',
            'intro' => 'Hver regel har fire dimensjoner, alle uavhengige av hverandre:',
            'scope_heading' => '1. Omfang',
            'scope_body' => 'Enten <strong>Standard</strong> (regelen gjelder saker i alle avdelinger) eller en <strong>bestemt avdeling</strong>. Oppløsning: en avdelingsspesifikk regel vinner over standarden for saker i den avdelingen. Uten en standardregel får avdelinger uten en egen regel ingen varsler.',
            'trigger_heading' => '2. Utløser',
            'trigger_body' => 'Enten <strong>Advarsel</strong> (saken har passert advarselsterskelen &mdash; mulig brudd) eller <strong>Brudd</strong> (saken har overskredet målet sitt &mdash; faktisk brudd). Hver av dem er sin egen regel, så du kan varsle ulike personer for hver.',
            'target_heading' => '3. Mål',
            'target_body' => 'Hvilken klokke som skal følges &mdash; <strong>Respons</strong>, <strong>Løsning</strong> eller <strong>Begge</strong>.',
            'recip_heading' => '4. Mottakere',
            'recip_intro' => 'En hvilken som helst kombinasjon av:',
            'recip_assignee' => '<strong>Den saken er tildelt</strong> &mdash; analytikeren som eier saken akkurat nå. Hoppes over hvis den ikke er tildelt.',
            'recip_teams' => '<strong>Medlemmer av teamene til saksavdelingen</strong> &mdash; alle analytikere i alle team som er knyttet til avdelingen saken ligger i. Dekker hele køen uten at du må vedlikeholde en distribusjonsliste.',
            'recip_specific' => '<strong>En bestemt analytiker</strong> &mdash; mønsteret med en «SLA-ansvarlig» eller «tjenesteleder», der det er en navngitt person og ikke en rolle.',
            'recip_custom' => '<strong>Egne e-postadresser</strong> &mdash; fritekst skilt med komma. Nyttig for delte innbokser (<code>sla-varsler@firma.no</code>), e-postbroer til Slack/Teams, eller distribusjonslister.',
            'tip' => 'Hver sak utløser høyst én e-post per (mål, utløser) &mdash; cron-jobben holder styr på hva som er sendt, i tabellen <code>sla_notifications_sent</code>. Så en advarsel utløses én gang, et brudd én gang, og der stopper det &mdash; ingen spamsløyfer.',
            'warn' => '<strong>Ingen regler = ingen e-poster.</strong> Selv om hver eneste sak i systemet bryter, skjer det ingenting før du legger til minst én regel. Start med et par på standardomfang, ett for advarsel og ett for brudd, så har du dekning for alt.',
        ],
        'cron' => [
            'heading' => 'Sette opp cron-jobben',
            'sub' => 'Skriptet som sjekker brudd, må kjøre etter en plan. Én gang hvert femte minutt er det som fungerer best.',
            'p1' => 'SLA-markørene du ser i grensesnittet (merkene i innboksen, panelene i lesefeltet) regnes ut fortløpende når en side lastes. Men e-poster om brudd kan bare sendes hvis <em>noe</em> sjekker sakene av seg selv, også når ingen ser på dem. Det noe er en planlagt oppgave &mdash; på Windows Oppgaveplanlegging, på Linux cron.',
            'p2' => 'Skriptet er <code>cron/sla_breach_check.php</code> i installasjonsmappen til FreeITSM. Det kan startes på to måter:',
            'cli_heading' => 'A. CLI (anbefalt på en server du styrer selv)',
            'cli_note' => 'Ingen autentisering er nødvendig &mdash; filrettighetene styrer allerede hvem som kan kjøre det.',
            'http_heading' => 'B. HTTP (for delt nettdrift eller planleggere andre steder)',
            'http_note' => 'Tokenet lages automatisk ved første installasjon og lagres i <code>system_settings</code> under nøkkelen <code>sla_cron_token</code> (32 heksadesimale tegn, omtrent 128 bits entropi). Finn ditt med:',
            'win_heading' => 'Oppgaveplanlegging i Windows',
            'win_intro' => 'Åpne Oppgaveplanlegging (<code>taskschd.msc</code>) og opprett en ny oppgave med disse innstillingene:',
            'tbl_field' => 'Felt',
            'tbl_value' => 'Verdi',
            'win_r1_k' => 'Navn',
            'win_r1_v' => 'FreeITSM &mdash; sjekk av SLA-brudd',
            'win_r2_k' => 'Kjør enten brukeren er logget på eller ikke',
            'win_r2_v' => 'Kryss av her',
            'win_r3_k' => 'Utløser',
            'win_r3_v' => 'Daglig, gjenta hver dag, gjenta hvert 5. minutt i 1 dag',
            'win_r4_k' => 'Handling',
            'win_r4_v' => 'Start et program',
            'win_r5_k' => 'Program/skript',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Legg til argumenter',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Start i',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Cron på Linux',
            'linux_intro' => 'Legg til én linje i crontab-en din (<code>crontab -e</code>):',
            'sec_heading' => 'Sikkerhet &mdash; hva som beskytter HTTP-endepunktet',
            'sec_intro' => 'Tre lag, alle håndhevet automatisk:',
            'sec_token' => '<strong>1. Token som delt hemmelighet</strong> &mdash; 128 tilfeldige bits per installasjon, sammenlignet med konstant tidsbruk for å hindre tidsangrep.',
            'sec_lockout' => '<strong>2. Utestenging per IP ved mislykket autentisering</strong> &mdash; mer enn 10 forsøk med feil token fra samme IP den siste timen utløser en utestenging med 429 i én time. Slår tilbake systematisk gjetting uten at du trenger fail2ban.',
            'sec_interval' => '<strong>3. Minste intervall mellom vellykkede kjøringer</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (standard 30 s). Selv en forespørsel med gyldig token får 429 hvis den kommer raskere enn dette etter forrige vellykkede kjøring. Slår tilbake dobbeltplanlegging ved uhell og løpske sløyfer.',
            'log_heading' => 'Aktivitetslogg',
            'log_body' => 'Hver kjøring (godtatt eller avvist) logges til tabellen <code>sla_cron_runs</code> med tidsbruk, resultat, antall og klientens IP. Se de siste 20 kjøringene i <strong>Cron-aktivitet</strong>-panelet nederst på SLA-innstillingsfanen &mdash; nyttig for å bekrefte at planen faktisk utløses, og for å granske mislykkede autentiseringsforsøk. Rader ryddes automatisk etter <code>sla_cron_log_retention_days</code> (standard 30), så tabellen holder seg liten.',
        ],
        'examples' => [
            'heading' => 'Gjennomgåtte eksempler',
            'sub' => 'Fra det enkle tilfellet med én tidssone til det vanskeligere på tvers av tidssoner, der «rettferdig» må defineres.',
            'ex1_heading' => 'Eksempel 1: Sak meldt i Storbritannia, servicedesk i Storbritannia',
            'ex1_title' => 'Det enkle tilfellet',
            'ex1_tag' => 'én tidssone',
            'ex1_setup' => '<strong>Oppsett:</strong> Én arbeidskalender kalt <em>Britisk kontor</em> med tidssonen <code>Europe/London</code>, man–fre 09.00–17.00, ingen helligdager. Prioriteten P2 har et responsmål på 1 time og et løsningsmål på 4 timer, begge mot kalenderen <em>Britisk kontor</em>.',
            'ex1_scenario' => '<strong>Scenario:</strong> Brukeren melder en P2-sak <strong>16.30 britisk tid på onsdag</strong>.',
            'ex1_timeline' => 'Ons. 16.30 britisk tid &mdash; <strong>saken opprettes</strong>, responsklokken starter.
Ons. 17.00 britisk tid &mdash; kontoret stenger, klokken settes på pause (30 min brukt av målet på 60 min).
Tors. 09.00 britisk tid &mdash; kontoret åpner, klokken går videre.
Tors. 09.30 britisk tid &mdash; analytikeren svarer. Respons-SLA-en er akkurat nådd (60 min brukt, mål på 60 min).',
            'ex1_outro' => 'Hadde ikke analytikeren svart før <strong>torsdag klokken 10.00 britisk tid</strong>, ville responsen vært <strong>i brudd med 30 minutter</strong> (90 min brukt mot målet på 60 min &mdash; 30 fra onsdag kveld, 60 fra torsdag morgen). Klokken på 1 time går bare i arbeidstiden, men en sak som kommer ved dagens slutt, spiser likevel opp mesteparten av budsjettet sitt over natten når kontoret åpner igjen &mdash; det er lett for en analytiker som kommer klokken 09.00, å tro at de har hele timen, når det i virkeligheten bare er 30 minutter igjen.',
            'ex2_heading' => 'Eksempel 2: Sak meldt i Storbritannia, servicedesk i Estland',
            'ex2_title' => 'Tilfellet på tvers av tidssoner',
            'ex2_tag' => '3 måter å definere «rettferdig» på',
            'ex2_setup' => '<strong>Oppsett:</strong> Britiske kunder (<code>Europe/London</code>, GMT/BST), estisk servicedesk (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 timer foran britisk tid</strong>). Begge desker jobber nominelt 09.00–17.00 lokal tid.',
            'ex2_scenario' => '<strong>Scenario:</strong> En britisk kunde melder en P2-sak <strong>16.30 britisk tid på fredag</strong> (= 18.30 estisk tid, etter at Estland har stengt). Første mulighet en estisk analytiker har til å jobbe med den, er mandag 09.00 estisk tid (= 07.00 britisk tid). Responsmålet er 1 time.',
            'ex2_question' => 'Hva bør SLA-en si? Det finnes tre svar som kan forsvares, hvert rettferdig i sin egen forstand. Du velger hvilken kalender prioriteten skal ha, ut fra hva tjenesteavtalen din lover.',
            'optA_label' => 'Alternativ A &mdash; med kunden i sentrum',
            'optA_p1' => '<strong>Sett prioriteten til å bruke en kalender med <em>britiske</em> timer.</strong> Klokken går mot britisk 09.00–17.00, uansett hvor analytikeren er.',
            'optA_p2' => 'I scenarioet over, sak meldt 16.30 britisk tid fredag: klokken går 16.30&ndash;17.00 britisk tid fredag (30 min brukt), settes på pause over natten og helgen, og går videre mandag 09.00 britisk tid. Svarer en estisk analytiker klokken 10.00 estisk tid mandag (= 08.00 britisk tid), er den britiske kalenderen fortsatt på pause (det britiske kontoret åpner 09.00 britisk tid), så det tikker ingen ekstra minutter &mdash; forbruket står på 30 min. <strong>SLA nådd med 30 min margin</strong>. Et svar etter 09.30 britisk tid (= 11.30 estisk tid) ville vært et brudd.',
            'optA_p3' => '<em>Rettferdig for:</em> kunden. Opplevelsen deres følger deres egen arbeidsdag.<br><em>Ulempen:</em> estiske analytikere forventes å være tilgjengelige 09.00–17.00 britisk tid (= 11.00–19.00 estisk tid), noe som forlenger arbeidsdagen deres med 2 timer.',
            'optB_label' => 'Alternativ B &mdash; med analytikeren i sentrum',
            'optB_p1' => '<strong>Sett prioriteten til å bruke en kalender med <em>estiske</em> timer.</strong> Klokken går mot estisk 09.00–17.00.',
            'optB_p2' => 'Samme scenario: saken meldes 18.30 estisk tid fredag (etter stengetid), klokken står på pause hele helgen og begynner å gå mandag 09.00 estisk tid (= 07.00 britisk tid). Svarer analytikeren 09.30 estisk tid mandag (= 07.30 britisk tid), har respons-SLA-en brukt 30 min av målet på 60 min &mdash; <strong>nådd med 30 min margin</strong>. Den britiske kunden meldte saken 16.30 britisk tid fredag og fikk svar 07.30 britisk tid mandag &mdash; ventetiden på klokken var mye lengre enn SLA-en antyder.',
            'optB_p3' => '<em>Rettferdig for:</em> analytikerne. De jobber normal arbeidstid.<br><em>Ulempen:</em> kunder i Storbritannia kan føle at SLA-en «lyver» hvis en sak fra fredag ettermiddag ikke bekreftes før mandag morgen estisk tid, mens rapporten sier at responstiden var 1 time. Sørg for at tjenesteavtalen din sier uttrykkelig at SLA-en går mot åpningstiden til servicedesken.',
            'optC_label' => 'Alternativ C &mdash; overlappsvindu (strengest)',
            'optC_p1' => '<strong>Sett prioriteten til å bruke en kalender som bare dekker timene der begge desker er åpne.</strong> Britisk 09.00–17.00 overlapper med estisk 09.00–17.00 (= britisk 07.00–15.00) i vinduet <strong>britisk 09.00–15.00</strong> &mdash; 6 timer per arbeidsdag.',
            'optC_p2' => 'Samme scenario: saken meldes 16.30 britisk tid fredag (utenfor overlappen, siden overlappen stenger 15.00 britisk tid), klokken står på pause over helgen og går videre mandag 09.00 britisk tid (= 11.00 estisk tid, øyeblikket overlappen åpner igjen). Svarer den estiske analytikeren 11.30 estisk tid (= 09.30 britisk tid), har respons-SLA-en brukt 30 min av målet på 60 min &mdash; <strong>nådd med 30 min margin</strong>. Svaret kom i overlappsvinduet, så det teller med én gang.',
            'optC_p3' => '<em>Rettferdig for:</em> begge sider &mdash; SLA-en går bare i timer der servicedesken faktisk kunne fått saken videre OG kunden sitter ved pulten sin og kan ta imot et svar.<br><em>Ulempen:</em> et kortere vindu per dag betyr lengre klokketid for å nå ambisiøse mål. Et løsningsmål på 4 timer strekker seg over 1,5 dager med overlapp, der det med en vanlig kalender på 8 timer ville vært gjort i løpet av én dag.',
            'choose_tip' => '<strong>Slik velger du:</strong> se på tjenesteavtalen din. Sier den «svar innen 1 time etter mottak» &mdash; da er det alternativ A (kundens klokke). Sier den «svar innen 1 arbeidstime» &mdash; da er det typisk alternativ B (den desken som er på jobb). Sier den «innen 1 time med gjensidig tilgjengelighet» &mdash; da er det alternativ C. Finnes det ingen avtale, spør teamet: vil dere kjenne presset utenfor estisk arbeidstid (alternativ A), eller vil dere at britiske kunder av og til skal føle seg oversett (alternativ B)?',
            'ex3_heading' => 'Eksempel 3: Pause på klokken mens man venter på en leverandør',
            'ex3_title' => 'Slik virker pausestatuser i praksis',
            'ex3_tag' => 'pause på klokken',
            'ex3_setup' => '<strong>Oppsett:</strong> Prioriteten P3 med et løsningsmål på 8 arbeidstimer, britisk kalender, og statusen «Venter på leverandør» merket <em>Setter SLA på pause</em>.',
            'ex3_scenario' => '<strong>Scenario:</strong> Saken meldes mandag 09.00 britisk tid. Analytikeren eskalerer til Microsoft mandag 11.00 britisk tid og flytter saken til «Venter på leverandør». Microsoft svarer onsdag 14.00 britisk tid. Analytikeren gjennomfører løsningen og lukker saken torsdag 10.00 britisk tid.',
            'ex3_timeline' => 'Man. 09.00 &mdash; saken opprettes, løsningsklokken går.
Man. 11.00 &mdash; flyttet til «Venter på leverandør», <strong>klokken settes på pause</strong> (2t brukt).
Ons. 14.00 &mdash; flyttet tilbake til «Under arbeid», <strong>klokken går videre</strong>.
Ons. 17.00 &mdash; kontoret stenger (5t brukt til sammen).
Tors. 09.00 &mdash; kontoret åpner.
Tors. 10.00 &mdash; saken lukkes (6t brukt til sammen). <strong>SLA nådd</strong> mot målet på 8t.',
            'ex3_outro' => 'Tid på klokken: omtrent 3 dager. Tid på SLA-en: 6 arbeidstimer. Uten merket for pausestatus ville SLA-en telt med alle de 2 dagene med venting på leverandøren, i tillegg til arbeidstiden, til sammen omtrent 18 arbeidstimer &mdash; godt over brudd.',
        ],
